127	    /** Whether this claim counts toward the totals: OPEN, PENDING and SETTLED claims do, unless deferred. */
128	    public boolean counts() {
129	        return !deferred && (status == ClaimStatus.OPEN || status == ClaimStatus.PENDING || status == ClaimStatus.SETTLED);
130	    }
