132	    /**
133	     * The status this claim had at the end of the day, as its status log records it (the last line on or before it);
134	     * null when it was not yet added then. A claim kept from before the log (no lines) has its status now.
135	     */
136	    public ClaimStatus statusOn(LocalDate end) {
137	        if (log == null || log.isEmpty()) {
138	            return status;
139	        }
140	        ClaimStatus then = null;
141	        for (ClaimLogLine line : log) {
142	            if (!LocalDate.parse(line.on()).isAfter(end)) {
143	                then = line.status();
144	            }
145	        }
146	        return then;
147	    }
