149	    /** Whether this claim's statement binds its figure: it is stated, and not PENDING (which shows its live figure). */
150	    public boolean bound() {
151	        return stated && status != ClaimStatus.PENDING;
152	    }
153	
154	    /**
155	     * Whether this claim keeps a figure whatever the rates: fixed when settled, or bound by a statement (a claim
156	     * settled or bound when its grade had no rate keeps none; a PENDING claim is not bound).
157	     */
158	    public boolean fixed() {
159	        return settledDue != null || (bound() && statedDue != null);
160	    }
161	
162	    /**
163	     * This claim's due: the due fixed when settled; else the greater of the sheet's floor in force on its date and its
164	     * {@link #figure} plus, while it is overdue, its late charge on that figure (a correction has no floor and no
165	     * charge); null when there is no figure.
166	     */
167	    public BigDecimal due(List<Rate> rates, String grade, Dated floor, Late late) {
168	        BigDecimal figure = figure(rates, grade, floor, late.rounding(this));
169	        if (figure == null || settledDue != null || correction()) {
170	            return figure;
171	        }
172	        return figure.add(late.charge(this, grade, figure)).max(floor.on(date));
173	    }
174	
175	    /**
176	     * This claim's figure: the due fixed when settled, else the rate figure its statement bound (unless PENDING), else
177	     * its amount at the grade's rate in force on its date (the floor is applied last, in {@link #due}); null when
178	     * there is none.
179	     */
180	    public BigDecimal figure(List<Rate> rates, String grade, Dated floor) {
181	        return figure(rates, grade, floor, RoundingMode.HALF_EVEN);
182	    }
183	
184	    /** This claim's {@link #figure}, its live figure rounded by the mode. */
185	    public BigDecimal figure(List<Rate> rates, String grade, Dated floor, RoundingMode rounding) {
186	        if (settledDue != null) {
187	            return new BigDecimal(settledDue);
188	        }
189	        if (bound()) {
190	            return statedDue == null ? null : new BigDecimal(statedDue);
191	        }
192	        return Rate.due(amount, Rate.on(rates, grade, LocalDate.parse(date)), rounding);
193	    }
