355	    /** The claim showing this number on the sheet (within its period, or on the sheet), or null when none does. */
356	    public Claim findByNumber(String sheet, String number) {
357	        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ?"
358	                + " AND COALESCE(claim.period_number, CAST(claim.number_on_sheet AS VARCHAR)) = ?", ROW, sheet, number);
359	        return found.isEmpty() ? null : found.get(0);
360	    }
361	
362	    /**
363	     * Adds the claim with its due-by and the terms it was fixed with; the due-by moves after only when a holiday is
364	     * added (see {@link #refixDueBy}); returns its id.
365	     */
366	    public long add(String sheet, long person, ClaimInput input, LocalDate dueBy, int terms) {
367	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
368	        jdbc.update(con -> {
369	            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, corrects, due_by, ref, tags, tags_ever, due_terms, listed)"
370	                    + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, " + NEXT_LISTED + ")", new String[] { "id" });
371	            ps.setString(1, sheet);
372	            ps.setLong(2, person);
373	            ps.setBigDecimal(3, input.amount());
374	            ps.setDate(4, Date.valueOf(input.date()));
375	            ps.setString(5, input.note());
376	            ps.setString(6, input.corrects());
377	            ps.setDate(7, Date.valueOf(dueBy));
378	            ps.setString(8, input.ref());
379	            ps.setString(9, kept(input.tags()));
380	            ps.setString(10, kept(input.tags()));
381	            ps.setInt(11, terms);
382	            ps.setString(12, sheet);
383	            return ps;
384	        }, keys);
385	        return keys.getKey().longValue();
386	    }
387	
388	    private record Fixed(long id, LocalDate date, int terms) {
389	    }
390	
391	    /**
392	     * Re-fixes the due-by of every claim on the sheet that is not SETTLED or VOID and whose due-by is on or after the
393	     * date: the terms-th business day after its date, with the terms it was fixed with, skipping weekends and the
394	     * holidays given.
395	     */
396	    public void refixDueBy(String sheet, LocalDate from, Set<LocalDate> holidays) {
397	        List<Fixed> fixed = jdbc.query("SELECT id, claimed_on, due_terms FROM claim WHERE sheet = ?"
398	                + " AND status NOT IN ('SETTLED', 'VOID') AND due_by >= ?",
399	                (rs, i) -> new Fixed(rs.getLong("id"), rs.getDate("claimed_on").toLocalDate(), rs.getInt("due_terms")),
400	                sheet, Date.valueOf(from));
401	        for (Fixed claim : fixed) {
402	            LocalDate dueBy = Holidays.businessDaysAfter(claim.date(), claim.terms(), holidays);
403	            jdbc.update("UPDATE claim SET due_by = ? WHERE sheet = ? AND id = ?", Date.valueOf(dueBy), sheet, claim.id());
404	        }
405	    }
406	
407	    /** Whether a claim on the sheet other than the one excluded (null for none) has the reference, ignoring case. */
408	    public boolean refUsed(String sheet, String ref, Long excluded) {
409	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet = ? AND LOWER(ref) = LOWER(?) AND id <> ?",
410	                Integer.class, sheet, ref, excluded == null ? -1L : excluded);
411	        return n != null && n > 0;
412	    }
413	
414	    /** Marks the claim a late entry: added while the period its due-by falls in was soft-closed. */
415	    public void setLateEntry(String sheet, long id) {
416	        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE sheet = ? AND id = ?", sheet, id);
417	    }
418	
419	    /**
420	     * Adds the OPEN claim split off another: the amount, with the date, note and tags of the claim it was split from
421	     * (by the number that claim shows), opened by the user, with its due-by fixed now; returns its id.
422	     */
423	    public long addSplit(String sheet, long person, BigDecimal amount, LocalDate date, String note, List<String> tags,
424	            LocalDate dueBy, int terms, String splitFrom, String openedBy) {
425	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
426	        jdbc.update(con -> {
427	            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, due_by, status,"
428	                    + " split_from, opened_by, tags, tags_ever, due_terms, listed) VALUES (?, ?, ?, ?, ?, ?, 'OPEN', ?, ?, ?, ?, ?, "
429	                    + NEXT_LISTED + ")",
430	                    new String[] { "id" });
431	            ps.setString(1, sheet);
432	            ps.setLong(2, person);
433	            ps.setBigDecimal(3, amount);
434	            ps.setDate(4, Date.valueOf(date));
435	            ps.setString(5, note);
436	            ps.setDate(6, Date.valueOf(dueBy));
437	            ps.setString(7, splitFrom);
438	            ps.setString(8, openedBy);
439	            ps.setString(9, kept(tags));
440	            ps.setString(10, kept(tags));
441	            ps.setInt(11, terms);
442	            ps.setString(12, sheet);
443	            return ps;
444	        }, keys);
445	        return keys.getKey().longValue();
446	    }
447	
448	    /**
449	     * Leaves an OPEN claim the rest of its amount once split, unbound from any statement; conditional on the
450	     * amount read and on it still being OPEN and not deferred: false when it no longer is.
451	     */
452	    public boolean split(String sheet, long id, BigDecimal was, BigDecimal rest) {
453	        return jdbc.update("UPDATE claim SET amount = ?, stated = FALSE, stated_due = NULL WHERE sheet = ? AND id = ?"
454	                + " AND status = 'OPEN' AND amount = ? AND (deferred_until IS NULL OR deferred_until <="
455	                + " COALESCE((SELECT s.today FROM sheet s WHERE s.id = claim.sheet), CURRENT_DATE))",
456	                rest, sheet, id, was) == 1;
457	    }
458	
459	    /**
460	     * Edits a draft claim not locked by another user's editor, releasing any lock on it and recording the user as its
461	     * last editor: false when it is no longer a draft, or another user's editor holds it. The tags it carried before stay among those it has ever carried.
462	     */
463	    public boolean update(String sheet, long id, ClaimInput input, List<String> tagsEver, String user) {
464	        List<String> ever = Stream.concat(tagsEver.stream(), input.tags().stream()).distinct().sorted().toList();
465	        return jdbc.update(
466	                "UPDATE claim SET amount = ?, claimed_on = ?, note = ?, corrects = ?, ref = ?, tags = ?, tags_ever = ?, locked_by = NULL, edited_by = ?"
467	                        + " WHERE sheet = ? AND id = ? AND status = 'DRAFT' AND (locked_by IS NULL OR locked_by = ?)",
468	                input.amount(), Date.valueOf(input.date()), input.note(), input.corrects(), input.ref(), kept(input.tags()),
469	                kept(ever), user, sheet, id, user) == 1;
470	    }
471	
472	    /** Marks the claim settled by the bulk settle batch with the number; null when settled one at a time. */
473	    public void setBatch(String sheet, long id, Integer batch) {
474	        jdbc.update("UPDATE claim SET batch = ? WHERE sheet = ? AND id = ?", batch, sheet, id);
475	    }
476	
477	    /** The user who last edited the claim (through its form or its amount entry); null when never edited. */
478	    public String editedBy(String sheet, long id) {
479	        return jdbc.query("SELECT edited_by FROM claim WHERE sheet = ? AND id = ?",
480	                rs -> rs.next() ? rs.getString(1) : null, sheet, id);
481	    }
482	
483	    /**
484	     * Locks a draft claim for the user's editor, releasing any other claim the user's editor held on the sheet:
485	     * false when it is no longer a draft, or another user's editor holds it.
486	     */
487	    public boolean lock(String sheet, long id, String user) {
488	        if (jdbc.update("UPDATE claim SET locked_by = ? WHERE sheet = ? AND id = ? AND status = 'DRAFT'"
489	                + " AND (locked_by IS NULL OR locked_by = ?)", user, sheet, id, user) != 1) {
490	            return false;
491	        }
492	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND id <> ? AND locked_by = ?", sheet, id, user);
493	        return true;
494	    }
495	
496	    /** Releases the claim's lock when the user's editor holds it. */
497	    public void unlock(String sheet, long id, String user) {
498	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND id = ? AND locked_by = ?", sheet, id, user);
499	    }
500	
501	    /** Releases every lock on the sheet's claims, as when its today changes. */
502	    public void unlockAll(String sheet) {
503	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND locked_by IS NOT NULL", sheet);
504	    }
505	
506	    /**
507	     * Moves the claim of the person and status it was read with to another person, unbound from any statement and
508	     * listed as the sheet's newest: false when it no longer has that person or status.
509	     */
510	    public boolean reassign(String sheet, long id, long from, ClaimStatus status, long to) {
511	        return jdbc.update("UPDATE claim SET person = ?, stated = FALSE, stated_due = NULL, listed = " + NEXT_LISTED
512	                + " WHERE sheet = ? AND id = ? AND person = ? AND status = ?", to, sheet, sheet, id, from,
513	                status.name()) == 1;
514	    }
515	
516	    /**
517	     * Moves the claim of the status and date it was read with to another date, keeping its due-by and any figure its
518	     * statement bound: false when it no longer has that status or date.
519	     */
520	    public boolean redate(String sheet, long id, ClaimStatus status, LocalDate was, LocalDate date) {
521	        return jdbc.update("UPDATE claim SET claimed_on = ? WHERE sheet = ? AND id = ? AND status = ? AND claimed_on = ?",
522	                Date.valueOf(date), sheet, id, status.name(), Date.valueOf(was)) == 1;
523	    }
524	
525	    /** Moves the claim from one status to another: false when it no longer has the status it was read with. */
526	    public boolean changeStatus(String sheet, long id, ClaimStatus from, ClaimStatus to) {
527	        return jdbc.update("UPDATE claim SET status = ? WHERE sheet = ? AND id = ? AND status = ?", to.name(), sheet,
528	                id, from.name()) == 1;
529	    }
530	
531	    /** Defers an OPEN claim until the date: false when it is no longer OPEN. */
532	    public boolean defer(String sheet, long id, LocalDate until) {
533	        return jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet = ? AND id = ? AND status = 'OPEN'",
534	                Date.valueOf(until), sheet, id) == 1;
535	    }
536	
537	    /**
538	     * Reminds an OPEN or PENDING claim on the date (the sheet's today), conditional on its status read and on it not
539	     * yet being reminded that day: false when it was not.
540	     */
541	    public boolean remind(String sheet, long id, ClaimStatus status, LocalDate today) {
542	        return jdbc.update("UPDATE claim SET reminded_on = ? WHERE sheet = ? AND id = ? AND status = ?"
543	                + " AND (reminded_on IS NULL OR reminded_on <> ?)", Date.valueOf(today), sheet, id, status.name(),
544	                Date.valueOf(today)) == 1;
545	    }
546	
547	    /**
548	     * Raises the claim's proofs count by one, conditional on the status and count read, so a concurrent change by
549	     * another user is refused, not overwritten: false when it was not.
550	     */
551	    public boolean addProof(String sheet, long id, ClaimStatus status, int was) {
552	        return jdbc.update("UPDATE claim SET proofs = proofs + 1 WHERE sheet = ? AND id = ? AND status = ? AND proofs = ?",
553	                sheet, id, status.name(), was) == 1;
554	    }
555	
556	    /** Fixes the claim's due as it is settled, or leaves none with null. */
557	    public void setSettledDue(String sheet, long id, BigDecimal due) {
558	        jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ?", due, sheet, id);
559	    }
560	
561	    /**
562	     * Re-fixes a SETTLED claim's due (null for none), conditional on the due read, so a concurrent change by another
563	     * user is refused, not overwritten; false when it was not.
564	     */
565	    public boolean resettle(String sheet, long id, BigDecimal was, BigDecimal due) {
566	        return jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ? AND status = ?"
567	                + " AND settled_due IS NOT DISTINCT FROM ?", due, sheet, id, ClaimStatus.SETTLED.name(), was) == 1;
568	    }
569	
570	    /** Binds the claim to a statement's figure (null when its grade had no rate), or unbinds it when not stated. */
571	    public void setStated(String sheet, long id, boolean stated, BigDecimal due) {
572	        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet = ? AND id = ?", stated, due, sheet, id);
573	    }
574	
575	    /** Unbinds every claim of the person bound by their last statement, so each is live again. */
576	    public void unbindPerson(String sheet, long person) {
577	        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet = ? AND person = ? AND stated",
578	                sheet, person);
579	    }
580	
581	    /** Records the user who opened the claim. */
582	    public void setOpenedBy(String sheet, long id, String user) {
583	        jdbc.update("UPDATE claim SET opened_by = ? WHERE sheet = ? AND id = ?", user, sheet, id);
584	    }
585	
586	    /** Sets the claim's number on the sheet, or clears it with null. */
587	    public void setNumber(String sheet, long id, Integer number) {
588	        jdbc.update("UPDATE claim SET number_on_sheet = ? WHERE sheet = ? AND id = ?", number, sheet, id);
589	    }
590	
591	    /** Sets the claim's number within its period. */
592	    public void setPeriodNumber(String sheet, long id, String periodNumber) {
593	        jdbc.update("UPDATE claim SET period_number = ? WHERE sheet = ? AND id = ?", periodNumber, sheet, id);
594	    }
595	
596	    /**
597	     * Takes the next number in the sheet's period of the name ("" for the claims in no period): 1 first, then 2,
598	     * and so on, each period counting on its own. Locked as {@link #nextNumber}.
599	     */
600	    public int nextPeriodNumber(String sheet, String period) {
601	        while (true) {
602	            if (jdbc.update("UPDATE claim_period_number SET last_number = last_number + 1 WHERE sheet = ? AND period = ?",
603	                    sheet, period) == 1) {
604	                return jdbc.queryForObject("SELECT last_number FROM claim_period_number WHERE sheet = ? AND period = ?",
605	                        Integer.class, sheet, period);
606	            }
607	            try {
608	                jdbc.update("INSERT INTO claim_period_number (sheet, period, last_number) VALUES (?, ?, 1)", sheet, period);
609	                return 1;
610	            } catch (DuplicateKeyException raced) {
611	                // Another user took the period's first number at the same moment: take the one after it.
612	            }
613	        }
614	    }
615	
616	    /**
617	     * Takes the next number of the sheet-wide sequence the sheet shares with the other sheets of its tree: the one
618	     * after the last number given on any of them (1 when none has given one), recorded as the sheet's last number.
619	     * The counter rows of the whole tree stay locked until the transaction ends, so two claims opened at once
620	     * anywhere in the tree get different numbers.
621	     */
622	    public int nextNumber(String sheet, List<String> tree) {
623	        try {
624	            jdbc.update("INSERT INTO claim_number (sheet, last_number) VALUES (?, 0)", sheet);
625	        } catch (DuplicateKeyException exists) {
626	            // The sheet has given a number already: its counter is in place.
627	        }
628	        java.util.TreeSet<String> sheets = new java.util.TreeSet<>(tree);
629	        sheets.add(sheet);
630	        String in = String.join(", ", java.util.Collections.nCopies(sheets.size(), "?"));
631	        List<Integer> lasts = jdbc.queryForList("SELECT last_number FROM claim_number WHERE sheet IN (" + in
632	                + ") ORDER BY sheet FOR UPDATE", Integer.class, sheets.toArray());
633	        int next = lasts.stream().mapToInt(Integer::intValue).max().orElse(0) + 1;
634	        jdbc.update("UPDATE claim_number SET last_number = ? WHERE sheet = ?", next, sheet);
635	        return next;
636	    }
637	
638	    /**
639	     * Takes the next number of the fiscal year's sequence (FY<yyyy>) the sheet shares with the other sheets of its
640	     * tree: the one after the last number given in that year on any of them (1 when none has given one), recorded as
641	     * the sheet's last number in it. Locked as {@link #nextNumber}.
642	     */
643	    public int nextFiscalYearNumber(String sheet, List<String> tree, String fy) {
644	        try {
645	            jdbc.update("INSERT INTO claim_fy_number (sheet, fy, last_number) VALUES (?, ?, 0)", sheet, fy);
646	        } catch (DuplicateKeyException exists) {
647	            // The sheet has given a number in this fiscal year already: its counter is in place.
648	        }
649	        java.util.TreeSet<String> sheets = new java.util.TreeSet<>(tree);
650	        sheets.add(sheet);
651	        String in = String.join(", ", java.util.Collections.nCopies(sheets.size(), "?"));
652	        List<Object> args = new java.util.ArrayList<>();
653	        args.add(fy);
654	        args.addAll(sheets);
655	        List<Integer> lasts = jdbc.queryForList("SELECT last_number FROM claim_fy_number WHERE fy = ? AND sheet IN (" + in
656	                + ") ORDER BY sheet FOR UPDATE", Integer.class, args.toArray());
657	        int next = lasts.stream().mapToInt(Integer::intValue).max().orElse(0) + 1;
658	        jdbc.update("UPDATE claim_fy_number SET last_number = ? WHERE sheet = ? AND fy = ?", next, sheet, fy);
659	        return next;
660	    }
661	}
