13	/**
14	 * A person on a sheet: name (unique on the sheet, ignoring case) and grades (A, B or C), each in force from its
15	 * from-date; grade is the one in force on the sheet's today. The version is raised by one on every save. The
16	 * retired-from date (yyyy-mm-dd) is null unless they are retired; once it is set they count as retired, whatever
17	 * the date. Their holds are listed in the order they were added; their OPEN claims dated within a hold, unless bound
18	 * by a statement, count in no live total. Their own terms (days) are null when they have none. retiredNow is whether
19	 * the sheet's today is on or after their retired-from date: from then their OPEN and PENDING claims, unless bound by a
20	 * statement, count in no live total. Their contact (trimmed, lower-cased, not another's on the sheet) is null when they
21	 * have none. clashing is whether their name or one of their aliases is already a name or alias on another sheet of
22	 * the sheet's tree (its ancestors and descendants): every edit of them is refused until it renames them out of it.
23	 * Their origin is the sheet they were transferred from, null for anyone not transferred. Their retirements are the
24	 * past ones (each ended by unretiring them), in the order they were unretired. Their tags are lower-cased, repeats
25	 * dropped, sorted: a claim of theirs counts in the due-total of each.
26	 */
27	public record Person(long id, String name, String grade, long version, String retiredFrom, List<Hold> holds,
28	        List<GradeFrom> grades, Integer terms, boolean retiredNow, String contact, boolean clashing, String origin,
29	        List<Retirement> retirements, List<String> tags) {
30	
31	    /**
32	     * Whether the claim, theirs, counts toward the live totals: it counts, unless it is open, not bound by a statement,
33	     * and dated within one of their holds or their retirement date is reached.
34	     */
35	    public boolean counts(Claim claim) {
36	        if (!claim.counts()) {
37	            return false;
38	        }
39	        if (claim.status() == ClaimStatus.SETTLED || claim.bound()) {
40	            return true;
41	        }
42	        return !retiredNow && holds.stream().noneMatch((h) -> h.covers(claim.date()));
43	    }
44	
45	    /** This person as they stand with the date for the sheet's today: their grade in force then, and retired then or not. */
46	    public Person on(LocalDate today) {
47	        return new Person(id, name, gradeOn(grades, today), version, retiredFrom, holds, grades, terms,
48	                retiredOn(retiredFrom, today), contact, clashing, origin, retirements, tags);
49	    }
50	
51	    /** Whether the sheet's today is on or after the retired-from date (null: never retired). */
52	    static boolean retiredOn(String retiredFrom, LocalDate today) {
53	        return retiredFrom != null && !today.isBefore(LocalDate.parse(retiredFrom));
54	    }
55	
56	    /**
57	     * Whether the claim, theirs, counts toward a period ending on the date: by the status it had at the end of that
58	     * day (OPEN, PENDING or SETTLED; not yet added: no), unless deferred now, or open now, not bound by a statement
59	     * and dated within one of their holds or their retirement date is reached.
60	     */
61	    public boolean countsOn(Claim claim, LocalDate end) {
62	        ClaimStatus then = claim.statusOn(end);
63	        if (claim.deferred() || then == null) {
64	            return false;
65	        }
66	        if (then == ClaimStatus.SETTLED) {
67	            return true;
68	        }
69	        if (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) {
70	            return false;
71	        }
72	        return (claim.status() != ClaimStatus.OPEN && claim.status() != ClaimStatus.PENDING) || claim.bound()
73	                || (!retiredNow && holds.stream().noneMatch((h) -> h.covers(claim.date())));
74	    }
75	
76	    /**
77	     * Whether a claim dated {@code date} is after this person's retirement, or after the from and before the to of a
78	     * past one, and so refused.
79	     */
80	    public boolean retiredBefore(LocalDate date) {
81	        return (retiredFrom != null && date.isAfter(LocalDate.parse(retiredFrom)))
82	                || retirements.stream().anyMatch((r) -> r.within(date.toString()));
83	    }
84	
85	    /** The grade in force on the date: the one whose from-date is the latest on or before it (null when none). */
86	    public String gradeOn(LocalDate date) {
87	        return gradeOn(grades, date);
88	    }
89	
90	    /**
91	     * Whether the claim has a figure apart from the grade in force on {@code today}: one it keeps (settled or
92	     * bound), one at another grade, in force on its date, or one from a rate that ended (its to-date) on or before
93	     * today, the claim not being dated after today. Their due-total is n/a only when no claim does and that grade
94	     * has no rate on today.
95	     */
96	    public boolean figureApartFrom(Claim claim, LocalDate today, List<Rate> rates, Dated floor) {
97	        String then = gradeOn(claim.date());
98	        return claim.fixed()
99	                || (then != null && !then.equals(gradeOn(today)) && claim.figure(rates, then, floor) != null)
100	                || (then != null && !LocalDate.parse(claim.date()).isAfter(today)
101	                        && claim.figure(rates, then, floor) != null);
102	    }
103	
104	    /**
105	     * The due-by of a claim of theirs dated {@code date}, fixed when it is made: the terms-th business day after the
106	     * date (skipping weekends and the sheet's holidays as they stand now), the terms being the first of their own
107	     * terms, the terms of their grade then, and the sheet's terms then.
108	     */
109	    public LocalDate dueBy(String sheet, LocalDate date, Settings settings, Holidays holidays) {
110	        return holidays.businessDaysAfter(sheet, date, termsOn(sheet, date, settings));
111	    }
112	
113	    /** The terms a claim of theirs dated {@code date} is fixed with: their own, else their grade's then, else the sheet's then. */
114	    public int termsOn(String sheet, LocalDate date, Settings settings) {
115	        return terms != null ? terms : settings.terms(sheet, gradeOn(date), date);
116	    }
117	
118	    /** The grade in force on the claim's date (yyyy-mm-dd). */
119	    public String gradeOn(String date) {
120	        return gradeOn(LocalDate.parse(date));
121	    }
122	
123	    static String gradeOn(List<GradeFrom> grades, LocalDate date) {
124	        GradeFrom found = null;
125	        for (GradeFrom g : grades) {
126	            if (g.from() != null && LocalDate.parse(g.from()).isAfter(date)) {
127	                continue;
128	            }
129	            if (found == null || (found.from() != null && g.from() != null && g.from().compareTo(found.from()) > 0)
130	                    || (found.from() == null && g.from() != null)) {
131	                found = g;
132	            }
133	        }
134	        return found == null ? null : found.grade();
135	    }
