347	    public boolean contactTaken(String sheet, String contact, Long except) {
348	        Integer taken = jdbc.queryForObject(
349	                "SELECT COUNT(*) FROM person WHERE sheet = ? AND contact = ? AND (? IS NULL OR id <> ?)",
