358	
359	    /** Unretire the person on the date, keeping the retirement from its from-date to that date as a past one. */
360	    public void unretire(String sheet, long id, LocalDate from, LocalDate on) {
361	        jdbc.update("INSERT INTO person_retirement (person_id, from_date, to_date) VALUES (?, ?, ?)", id,
362	                Date.valueOf(from), Date.valueOf(on));
363	        jdbc.update("UPDATE person SET retired_from = NULL WHERE sheet = ? AND id = ?", sheet, id);
364	    }
