366	    /** Adds a hold to the person. */
367	    public void hold(long id, Hold hold) {
368	        jdbc.update("INSERT INTO person_hold (person_id, from_date, to_date) VALUES (?, ?, ?)", id,
369	                Date.valueOf(hold.from()), hold.to() == null ? null : Date.valueOf(hold.to()));
