372	    /** Save the person's name over the version it carries, raising the version; refused when it has moved on. */
373	    public void update(String sheet, Person person) throws DuplicatePersonNameException, StalePersonException {
374	        if (nameTaken(sheet, person.name(), person.id()) || aliases.taken(sheet, person.name())) {
375	            throw new DuplicatePersonNameException(person.name());
376	        }
377	        int updated;
378	        try {
379	            updated = jdbc.update(
380	                    "UPDATE person SET name = ?, version = version + 1 WHERE sheet = ? AND id = ? AND version = ?",
381	                    person.name(), sheet, person.id(), person.version());
382	        } catch (DuplicateKeyException e) {
