401	
402	/**
403	 * What makes an overdue claim's late charge: the sheet's late percent (two decimals) by date, the one in force on each 30-day boundary after the claim's due-by, and its today; a claim is due
404	 * by the due-by fixed when it was added. The charge is never bound by a statement: it follows the sheet's today.
405	 * It also carries the sheet's policy date, which decides how a claim's live figures round, and each grade's grace
406	 * as recorded by from-date: the days a claim of a person whose grade in force on its date has a grace in force on
407	 * that date is given past its due-by before it is overdue.
408	 */
409	public record Late(Dated pct, LocalDate today, LocalDate policy, Map<String, List<DatedValue>> grace) {
410	
411	    /**
412	     * How the claim's live figures round: half up when it rounds on a date (its own, or for a correction the date of
413	     * the claim it corrects) before the policy date, half to even on or after it.
414	     */
415	    public RoundingMode rounding(Claim claim) {
416	        return LocalDate.parse(claim.roundsOn()).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
417	    }
418	
419	    /**
420	     * The date the claim's overdue days are counted from: its due-by (fixed when it was added) plus the grace of the
421	     * grade (its person's in force on its date; null for none) in force on its date, if any.
422	     */
423	    public LocalDate graceBy(Claim claim, String grade) {
424	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
425	        List<DatedValue> history = grade == null ? null : grace.get(grade);
426	        String days = history == null ? "" : Settings.on(history, LocalDate.parse(claim.date()));
427	        return days.isEmpty() ? dueBy : dueBy.plusDays(Integer.parseInt(days));
428	    }
429	
430	    /** Whether the claim is overdue: OPEN or PENDING, not deferred, with its {@link #graceBy} before the sheet's today. */
431	    public boolean overdue(Claim claim, String grade) {
432	        return !claim.deferred() && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING) && graceBy(claim, grade).isBefore(today);
433	    }
434	
435	    /**
436	     * The claim's late charge on its figure, compounding: for each full 30 days it is overdue, the late percent in force
437	     * on that boundary (its {@link #graceBy} plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries
438	     * before it, rounded in hundredths by the claim's {@link #rounding}, the charges added up (a boundary at 0.00 adds
439	     * nothing); 0.00 when it is not overdue, and always for a correction.
440	     */
441	    public BigDecimal charge(Claim claim, String grade, BigDecimal figure) {
442	        BigDecimal total = BigDecimal.ZERO.setScale(2);
443	        if (figure == null || claim.correction() || !overdue(claim, grade)) {
444	            return total;
445	        }
446	        LocalDate dueBy = graceBy(claim, grade);
447	        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
448	        for (long k = 1; k <= periods; k++) {
449	            BigDecimal boundaryPct = pct.on(dueBy.plusDays(30 * k));
450	            if (boundaryPct.signum() != 0) {
451	                total = total.add(figure.add(total).multiply(boundaryPct).movePointLeft(2).setScale(2, rounding(claim)));
452	            }
453	        }
454	        return total;
455	    }
456	}
