459	/**
460	 * Where a claim is in its life: only OPEN, PENDING and SETTLED claims count toward the totals. A clerk's settle of a
461	 * due above the clerk limit makes it PENDING, which a steward approves (SETTLED) or rejects (back to OPEN). A steward
462	 * may void a SETTLED claim within 7 days of its settlement. A DRAFT may be DELETED (counting nowhere, not editable,
463	 * openable nor voidable), and restored to a DRAFT on the sheet-today it was deleted.
464	 */
465	public enum ClaimStatus {
466	    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED;
467	
468	    /** The status a change takes this claim to, or null when the change is not allowed from here. */
469	    public ClaimStatus after(ClaimStatusChange change) {
470	        return switch (change) {
471	            case OPEN -> this == DRAFT ? OPEN : null;
472	            case SETTLE -> this == OPEN ? SETTLED : null;
473	            case PEND -> this == OPEN ? PENDING : null;
474	            case APPROVE -> this == PENDING ? SETTLED : null;
475	            case REJECT -> this == PENDING ? OPEN : null;
476	            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED ? VOID : null;
477	            case DELETE -> this == DRAFT ? DELETED : null;
478	            case RESTORE -> this == DELETED ? DRAFT : null;
479	        };
480	    }
481	}
