502	/** Moves a claim to the status a change takes it to, refusing a change its status does not allow; shared by a
503	 *  claim's own status buttons and the bulk actions. */
504	@Service
505	public class ClaimStatusChanger {
506	
507	    /** How many days after its settlement a steward may still void a SETTLED claim. */
508	    public static final int VOID_SETTLED_DAYS = 7;
509	
510	    private final Claims claims;
511	    private final People people;
512	    private final Rates rates;
513	    private final Periods periods;
514	    private final Roles roles;
515	    private final Settings settings;
516	    private final SheetClock clock;
517	    private final Audit audit;
518	    private final Rollup rollup;
519	    private final ClaimLog log;
520	    private final Watches watches;
521	    private final SheetArchive archive;
522	    private final VoidReasons voidReasons;
523	
524	    public ClaimStatusChanger(Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
525	            SheetClock clock, Audit audit, Rollup rollup, ClaimLog log, Watches watches, SheetArchive archive,
526	            VoidReasons voidReasons) {
527	        this.claims = claims;
528	        this.people = people;
529	        this.rates = rates;
530	        this.periods = periods;
531	        this.roles = roles;
532	        this.settings = settings;
533	        this.clock = clock;
534	        this.audit = audit;
535	        this.rollup = rollup;
536	        this.log = log;
537	        this.watches = watches;
538	        this.archive = archive;
539	        this.voidReasons = voidReasons;
540	    }
541	
542	    /** Applies the change to the claim, writing nothing when it is refused. */
543	    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested)
544	            throws InvalidClaimStatusChangeException {
545	        change(sheet, user, claim, requested, null);
546	    }
547	
548	    /** Applies the change to the claim (a reject gives its reason, a void the one chosen from the sheet's void reasons),
549	     *  writing nothing when it is refused. */
550	    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason)
551	            throws InvalidClaimStatusChangeException {
552	        requested = vet(sheet, user, claim, requested, reason);
553	        String voidReason = requested == ClaimStatusChange.VOID && voidReasons.any(sheet) ? reason.trim() : null;
554	        Person person = people.find(sheet, claim.person());
555	        Rollup.Snapshot before = rollup.take(sheet);
556	        ClaimStatus next = claim.status().after(requested);
557	        // Conditional on the status read, so a concurrent change by another user is refused, not overwritten.
558	        if (next == null || !claims.changeStatus(sheet, claim.id(), claim.status(), next)) {
559	            throw new InvalidClaimStatusChangeException(
560	                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
561	        }
562	        // Opening gives the next number (FY<yyyy>-<n>) of its fiscal year its sheet's tree shares, or, while the sheet numbers by period from on or
563	        // before its today, the next number in the claim's period (X for none); a voided claim keeps the number it
564	        // had (never reused).
565	        Claim changed = claim;
566	        if (requested == ClaimStatusChange.OPEN) {
567	            changed = number(sheet, claim);
568	            claims.setOpenedBy(sheet, claim.id(), user);
569	        }
570	        String fields = changed.statusAuditFields(person.name());
571	        // Settling (or approving a PENDING claim, its live figure then) fixes the due at the person's grade rate in force on the claim's date (or the figure its
572	        // statement bound), with its late charge frozen in; with no rate there is nothing to fix, so it stays live.
573	        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
574	            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
575	                    settings.late(sheet, clock.today(sheet)));
576	            claims.setSettledDue(sheet, claim.id(), due);
577	            fields += " due=" + (due == null ? "n/a" : due.toPlainString());
578	        }
579	        // Voiding a SETTLED claim reverses its frozen figure out of every total.
580	        if (requested == ClaimStatusChange.VOID && claim.status() == ClaimStatus.SETTLED) {
581	            fields += " reversed=" + (claim.settledDue() == null ? "n/a" : claim.settledDue());
582	        }
583	        if (requested == ClaimStatusChange.REJECT) {
584	            fields += " reason=" + reason.trim();
585	        }
586	        if (voidReason != null) {
587	            voidReasons.voided(sheet, claim.id(), voidReason);
588	            fields += " reason=" + voidReason;
589	        }
590	        log.record(sheet, user, claim.id());
591	        audit.record(requested.event() + " sheet=" + sheet + " by=" + user + " " + fields);
592	        // Settling or approving tells each user watching the person, before the rollup lines.
593	        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
594	            watches.notify(sheet, user, person.id(), person.name(), changed.shownNumber());
595	        }
596	        rollup.record(sheet, user, before);
597	    }
598	
599	    /** Refuses the change the user may not make to the claim as it is now, writing nothing; otherwise gives the change
600	     *  it makes (a clerk's settle above the clerk limit is a move to PENDING). */
601	    public ClaimStatusChange vet(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason)
602	            throws InvalidClaimStatusChangeException {
603	        // A viewer changes nothing.
604	        if (Role.VIEWER.equals(roles.of(sheet, user))) {
605	            throw new InvalidClaimStatusChangeException("A viewer cannot change a claim");
606	        }
607	        if (archive.archived(sheet)) {
608	            throw new InvalidClaimStatusChangeException("An archived sheet cannot change");
609	        }
610	        // The permission matrix says which roles open, settle and void a claim.
611	        if ((requested == ClaimStatusChange.OPEN || requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.VOID)
612	                && !settings.permits(sheet, requested.name().toLowerCase(), roles.of(sheet, user))) {
613	            throw new InvalidClaimStatusChangeException("Your role may not " + requested.name().toLowerCase() + " a claim");
614	        }
615	        if (periods.closedOn(sheet, LocalDate.parse(claim.dueBy()))) {
616	            throw new InvalidClaimStatusChangeException("A claim due inside a closed period cannot change status");
617	        }
618	        // A steward voids a SETTLED claim only within 7 days of its settlement (its status log's last SETTLED date).
619	        if (requested == ClaimStatusChange.VOID && claim.status() == ClaimStatus.SETTLED) {
620	            if (!Role.STEWARD.equals(roles.of(sheet, user))) {
621	                throw new InvalidClaimStatusChangeException("Only a steward voids a settled claim");
622	            }
623	            LocalDate settled = claim.settledOn();
624	            LocalDate today = clock.today(sheet);
625	            if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
626	                throw new InvalidClaimStatusChangeException(
627	                        "A settled claim may be voided only within " + VOID_SETTLED_DAYS + " days of its settlement");
628	            }
629	        }
630	        // A DELETED claim is restored only on the sheet's today it was deleted (its status log's last DELETED date).
631	        if (requested == ClaimStatusChange.RESTORE && claim.status() == ClaimStatus.DELETED
632	                && !clock.today(sheet).equals(claim.deletedOn())) {
633	            throw new InvalidClaimStatusChangeException("A deleted claim may be restored only on the day it was deleted");
634	        }
635	        if (requested == ClaimStatusChange.SETTLE && claim.deferred()) {
636	            throw new InvalidClaimStatusChangeException("A deferred claim cannot be settled until its date");
637	        }
638	        // Four eyes: the user who opened a claim may not settle it, nor approve it.
639	        if ((requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
640	                && user.equals(claim.openedBy())) {
641	            throw new InvalidClaimStatusChangeException("The user who opened a claim cannot settle or approve it");
642	        }
643	        // Nor may the user who last edited it.
644	        if ((requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
645	                && user.equals(claims.editedBy(sheet, claim.id()))) {
646	            throw new InvalidClaimStatusChangeException("The user who last edited a claim cannot settle or approve it");
647	        }
648	        // Only a steward approves or rejects a PENDING claim; a reject gives a reason.
649	        if ((requested == ClaimStatusChange.APPROVE || requested == ClaimStatusChange.REJECT)
650	                && !Role.STEWARD.equals(roles.of(sheet, user))) {
651	            throw new InvalidClaimStatusChangeException("Only a steward approves or rejects a claim");
652	        }
653	        if (requested == ClaimStatusChange.REJECT && (reason == null || reason.isBlank())) {
654	            throw new InvalidClaimStatusChangeException("A reject needs a reason");
655	        }
656	        // While the sheet has void reasons, a void needs one chosen from them (with none, a void takes no reason).
657	        if (requested == ClaimStatusChange.VOID && voidReasons.any(sheet)) {
658	            String voidReason = reason == null ? "" : reason.trim();
659	            if (voidReason.isEmpty() || !voidReasons.has(sheet, voidReason)) {
660	                throw new InvalidClaimStatusChangeException("A void needs a reason from the sheet's void reasons");
661	            }
662	        }
663	        Person person = people.find(sheet, claim.person());
664	        // A claim whose due is above the proof threshold in force on its date (its person's grade's then when it has
665	        // one, else the sheet's) is settled or approved only once it has
666	        // a proof (a due of n/a is above no threshold); checked before the clerk limit, so it never goes to PENDING.
667	        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
668	            BigDecimal threshold = settings.proofThreshold(sheet, person.gradeOn(claim.date()),
669	                    LocalDate.parse(claim.date()));
670	            if (threshold != null && claim.proofs() == 0) {
671	                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
672	                        settings.late(sheet, clock.today(sheet)));
673	                if (due != null && due.compareTo(threshold) > 0) {
674	                    throw new InvalidClaimStatusChangeException(
675	                            "A claim whose due is above the proof threshold needs a proof before it is settled or approved");
676	                }
677	            }
678	        }
679	        // A claim whose due is above the note threshold in force on its date is opened only with a note (a due of n/a
680	        // is above no threshold).
681	        if (requested == ClaimStatusChange.OPEN && (claim.note() == null || claim.note().isBlank())) {
682	            BigDecimal threshold = settings.noteThreshold(sheet, LocalDate.parse(claim.date()));
683	            if (threshold != null) {
684	                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
685	                        settings.late(sheet, clock.today(sheet)));
686	                if (due != null && due.compareTo(threshold) > 0) {
687	                    throw new InvalidClaimStatusChangeException(
688	                            "A claim whose due is above the note threshold needs a note before it is opened");
689	                }
690	            }
691	        }
692	        // A clerk settles only a due at or below the sheet's clerk limit (a due of n/a is within any limit); above
693	        // it the claim goes to PENDING for a steward to approve. A steward settles anything.
694	        if (requested == ClaimStatusChange.SETTLE && claim.status() == ClaimStatus.OPEN
695	                && Role.CLERK.equals(roles.of(sheet, user))) {
696	            BigDecimal limit = settings.clerkLimit(sheet);
697	            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
698	                    settings.late(sheet, clock.today(sheet)));
699	            if (limit != null && due != null && due.compareTo(limit) > 0) {
700	                requested = ClaimStatusChange.PEND;
701	            }
702	        }
703	        if (claim.status().after(requested) == null) {
704	            throw new InvalidClaimStatusChangeException(
705	                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
706	        }
707	        // A period with a cap lets each person have at most that many OPEN or PENDING claims due inside it.
708	        if (requested == ClaimStatusChange.OPEN) {
709	            Period period = periods.on(sheet, LocalDate.parse(claim.dueBy()));
710	            if (period != null && period.cap() != null) {
711	                long held = claims.list(sheet).stream()
712	                        .filter((c) -> c.person() == claim.person() && c.id() != claim.id())
713	                        .filter((c) -> c.status() == ClaimStatus.OPEN || c.status() == ClaimStatus.PENDING)
714	                        .filter((c) -> c.dueBy().compareTo(period.from()) >= 0 && c.dueBy().compareTo(period.to()) <= 0)
715	                        .count();
716	                if (held >= period.cap()) {
717	                    throw new InvalidClaimStatusChangeException("A person may have at most " + period.cap()
718	                            + " open claims in period " + period.name());
719	                }
720	            }
721	        }
722	        return requested;
723	    }
724	
725	    /**
726	     * Gives an opening claim the next number (FY<yyyy>-<n>) of its due-by's fiscal year in the sequence its sheet shares with its tree, or, while the sheet numbers by period from on or before its
727	     * today, the next number in the claim's period (X for none); returns the claim so numbered.
728	     */
729	    public Claim number(String sheet, Claim claim) {
730	        LocalDate from = settings.periodNumberingFrom(sheet);
731	        if (from != null && !clock.today(sheet).isBefore(from)) {
732	            String period = periods.nameOn(sheet, LocalDate.parse(claim.dueBy()));
733	            String key = period == null ? "" : period;
734	            Claim numbered = claim.withPeriodNumber((period == null ? "X" : period) + "-" + claims.nextPeriodNumber(sheet, key));
735	            claims.setPeriodNumber(sheet, claim.id(), numbered.periodNumber());
736	            return numbered;
737	        }
738	        // Sheet-wide numbering restarts each fiscal year (of the due-by, the date that places it in a period):
739	        // FY<yyyy>-<n>, kept as the number it shows.
740	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
741	        int start = settings.fiscalStartMonth(sheet);
742	        String fy = "FY" + (dueBy.getMonthValue() >= start ? dueBy.getYear() : dueBy.getYear() - 1);
743	        Claim numbered = claim.withPeriodNumber(fy + "-" + claims.nextFiscalYearNumber(sheet, settings.wholeTree(sheet), fy));
744	        claims.setPeriodNumber(sheet, claim.id(), numbered.periodNumber());
745	        return numbered;
746	    }
747	}
