package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.Settings;

/**
 * A person on a sheet: name (unique on the sheet, ignoring case) and grades (A, B or C), each in force from its
 * from-date; grade is the one in force on the sheet's today. The version is raised by one on every save. The
 * retired-from date (yyyy-mm-dd) is null unless they are retired; once it is set they count as retired, whatever
 * the date. Their holds are listed in the order they were added; their OPEN claims dated within a hold, unless bound
 * by a statement, count in no live total. Their own terms (days) are null when they have none. retiredNow is whether
 * the sheet's today is on or after their retired-from date: from then their OPEN and PENDING claims, unless bound by a
 * statement, count in no live total. Their contact (trimmed, lower-cased, not another's on the sheet) is null when they
 * have none. clashing is whether their name or one of their aliases is already a name or alias on another sheet of
 * the sheet's tree (its ancestors and descendants): every edit of them is refused until it renames them out of it.
 * Their origin is the sheet they were transferred from, null for anyone not transferred. Their retirements are the
 * past ones (each ended by unretiring them), in the order they were unretired. Their tags are lower-cased, repeats
 * dropped, sorted: a claim of theirs counts in the due-total of each.
 */
public record Person(long id, String name, String grade, long version, String retiredFrom, List<Hold> holds,
        List<GradeFrom> grades, Integer terms, boolean retiredNow, String contact, boolean clashing, String origin,
        List<Retirement> retirements, List<String> tags) {

    /**
     * Whether the claim, theirs, counts toward the live totals: it counts, unless it is open, not bound by a statement,
     * and dated within one of their holds or their retirement date is reached.
     */
    public boolean counts(Claim claim) {
        if (!claim.counts()) {
            return false;
        }
        if (claim.status() == ClaimStatus.SETTLED || claim.bound()) {
            return true;
        }
        return !retiredNow && holds.stream().noneMatch((h) -> h.covers(claim.date()));
    }

    /** This person as they stand with the date for the sheet's today: their grade in force then, and retired then or not. */
    public Person on(LocalDate today) {
        return new Person(id, name, gradeOn(grades, today), version, retiredFrom, holds, grades, terms,
                retiredOn(retiredFrom, today), contact, clashing, origin, retirements, tags);
    }

    /** Whether the sheet's today is on or after the retired-from date (null: never retired). */
    static boolean retiredOn(String retiredFrom, LocalDate today) {
        return retiredFrom != null && !today.isBefore(LocalDate.parse(retiredFrom));
    }

    /**
     * Whether the claim, theirs, counts toward a period ending on the date: by the status it had at the end of that
     * day (OPEN, PENDING or SETTLED; not yet added: no), unless deferred now, or open now, not bound by a statement
     * and dated within one of their holds or their retirement date is reached.
     */
    public boolean countsOn(Claim claim, LocalDate end) {
        ClaimStatus then = claim.statusOn(end);
        if (claim.deferred() || then == null) {
            return false;
        }
        if (then == ClaimStatus.SETTLED) {
            return true;
        }
        if (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) {
            return false;
        }
        return (claim.status() != ClaimStatus.OPEN && claim.status() != ClaimStatus.PENDING) || claim.bound()
                || (!retiredNow && holds.stream().noneMatch((h) -> h.covers(claim.date())));
    }

    /**
     * Whether a claim dated {@code date} is after this person's retirement, or after the from and before the to of a
     * past one, and so refused.
     */
    public boolean retiredBefore(LocalDate date) {
        return (retiredFrom != null && date.isAfter(LocalDate.parse(retiredFrom)))
                || retirements.stream().anyMatch((r) -> r.within(date.toString()));
    }

    /** The grade in force on the date: the one whose from-date is the latest on or before it (null when none). */
    public String gradeOn(LocalDate date) {
        return gradeOn(grades, date);
    }

    /**
     * Whether the claim has a figure apart from the grade in force on {@code today}: one it keeps (settled or
     * bound), one at another grade, in force on its date, or one from a rate that ended (its to-date) on or before
     * today, the claim not being dated after today. Their due-total is n/a only when no claim does and that grade
     * has no rate on today.
     */
    public boolean figureApartFrom(Claim claim, LocalDate today, List<Rate> rates, Dated floor) {
        String then = gradeOn(claim.date());
        return claim.fixed()
                || (then != null && !then.equals(gradeOn(today)) && claim.figure(rates, then, floor) != null)
                || (then != null && !LocalDate.parse(claim.date()).isAfter(today)
                        && claim.figure(rates, then, floor) != null);
    }

    /**
     * The due-by of a claim of theirs dated {@code date}, fixed when it is made: the terms-th business day after the
     * date (skipping weekends and the sheet's holidays as they stand now), the terms being the first of their own
     * terms, the terms of their grade then, and the sheet's terms then.
     */
    public LocalDate dueBy(String sheet, LocalDate date, Settings settings, Holidays holidays) {
        return holidays.businessDaysAfter(sheet, date, termsOn(sheet, date, settings));
    }

    /** The terms a claim of theirs dated {@code date} is fixed with: their own, else their grade's then, else the sheet's then. */
    public int termsOn(String sheet, LocalDate date, Settings settings) {
        return terms != null ? terms : settings.terms(sheet, gradeOn(date), date);
    }

    /** The grade in force on the claim's date (yyyy-mm-dd). */
    public String gradeOn(String date) {
        return gradeOn(LocalDate.parse(date));
    }

    static String gradeOn(List<GradeFrom> grades, LocalDate date) {
        GradeFrom found = null;
        for (GradeFrom g : grades) {
            if (g.from() != null && LocalDate.parse(g.from()).isAfter(date)) {
                continue;
            }
            if (found == null || (found.from() != null && g.from() != null && g.from().compareTo(found.from()) > 0)
                    || (found.from() == null && g.from() != null)) {
                found = g;
            }
        }
        return found == null ? null : found.grade();
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.alias.Aliases;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people kept per sheet, each with their grades by from-date. */
@Repository
public class People {

    private static final String COLUMNS = "SELECT id, name, version, retired_from, terms, contact, origin, tags FROM person";

    private record Row(long id, String name, long version, String retiredFrom, Integer terms, String contact, String origin, String tags) {
    }

    private final JdbcTemplate jdbc;
    private final SheetClock clock;
    private final Aliases aliases;
    private final Settings settings;

    public People(JdbcTemplate jdbc, SheetClock clock, Aliases aliases, Settings settings) {
        this.jdbc = jdbc;
        this.clock = clock;
        this.aliases = aliases;
        this.settings = settings;
    }

    /** Every name and alias, lower-cased, on the other sheets of the sheet's tree (its ancestors and descendants). */
    private Set<String> treeNames(String sheet) {
        Set<String> names = new HashSet<>();
        for (String other : settings.tree(sheet)) {
            names.addAll(jdbc.queryForList("SELECT name_key FROM person WHERE sheet = ?", String.class, other));
            names.addAll(jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet = ?", String.class, other));
        }
        return names;
    }

    /** Whether the name is already a name or alias on another sheet of the sheet's tree, ignoring case. */
    public boolean usedInTree(String sheet, String name) {
        return treeNames(sheet).contains(name.toLowerCase(Locale.ROOT));
    }

    /** Whether an alias of the person is already a name or alias on another sheet of the sheet's tree. */
    public boolean aliasClashes(String sheet, long id) {
        Set<String> names = treeNames(sheet);
        return jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet = ? AND person_id = ?", String.class,
                sheet, id).stream().anyMatch(names::contains);
    }

    private List<Person> query(String sheet, String where, Object... args) {
        List<Row> rows = jdbc.query(COLUMNS + " " + where, (rs, i) -> new Row(rs.getLong("id"), rs.getString("name"),
                rs.getLong("version"),
                rs.getDate("retired_from") == null ? null : rs.getDate("retired_from").toLocalDate().toString(),
                rs.getObject("terms", Integer.class), rs.getString("contact"), rs.getString("origin"), rs.getString("tags")), args);
        if (rows.isEmpty()) {
            return List.of();
        }
        Map<Long, List<GradeFrom>> grades = new HashMap<>();
        jdbc.query("SELECT g.person_id, g.grade, g.from_date FROM person_grade g JOIN person p ON p.id = g.person_id"
                + " WHERE p.sheet = ? ORDER BY g.person_id, g.from_key", (rs) -> {
                    grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new GradeFrom(rs.getString("grade"),
                                    rs.getDate("from_date") == null ? null : rs.getDate("from_date").toLocalDate().toString()));
                }, sheet);
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT h.person_id, h.from_date, h.to_date FROM person_hold h JOIN person p ON p.id = h.person_id"
                + " WHERE p.sheet = ? ORDER BY h.person_id, h.id", (rs) -> {
                    holds.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new Hold(rs.getDate("from_date").toLocalDate().toString(),
                                    rs.getDate("to_date") == null ? null : rs.getDate("to_date").toLocalDate().toString()));
                }, sheet);
        Map<Long, List<Retirement>> retirements = new HashMap<>();
        jdbc.query("SELECT r.person_id, r.from_date, r.to_date FROM person_retirement r JOIN person p ON p.id = r.person_id"
                + " WHERE p.sheet = ? ORDER BY r.person_id, r.id", (rs) -> {
                    retirements.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new Retirement(rs.getDate("from_date").toLocalDate().toString(),
                                    rs.getDate("to_date").toLocalDate().toString()));
                }, sheet);
        Set<String> tree = treeNames(sheet);
        Map<Long, List<String>> aliasKeys = new HashMap<>();
        jdbc.query("SELECT person_id, alias_key FROM person_alias WHERE sheet = ?", (rs) -> {
            aliasKeys.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>()).add(rs.getString("alias_key"));
        }, sheet);
        LocalDate today = clock.today(sheet);
        List<Person> people = new ArrayList<>();
        for (Row r : rows) {
            List<GradeFrom> mine = List.copyOf(grades.getOrDefault(r.id(), List.of()));
            people.add(new Person(r.id(), r.name(), Person.gradeOn(mine, today), r.version(), r.retiredFrom(),
                    List.copyOf(holds.getOrDefault(r.id(), List.of())), mine, r.terms(),
                    Person.retiredOn(r.retiredFrom(), today), r.contact(),
                    tree.contains(r.name().toLowerCase(Locale.ROOT))
                            || aliasKeys.getOrDefault(r.id(), List.of()).stream().anyMatch(tree::contains), r.origin(),
                    List.copyOf(retirements.getOrDefault(r.id(), List.of())),
                    r.tags().isEmpty() ? List.of() : List.of(r.tags().split(","))));
        }
        return people;
    }

    /** Everyone on the sheet, in list order (by position; new people go to the end). */
    public List<Person> list(String sheet) {
        return query(sheet, "WHERE sheet = ? ORDER BY list_position, id", sheet);
    }

    /** The position after the sheet's last, where a new person goes. */
    public static final String NEXT_POSITION = "(SELECT COALESCE(MAX(n.list_position), 0) + 1 FROM person n WHERE n.sheet = ?)";

    /** Swaps the list positions of two people on the sheet. */
    public void swapPositions(String sheet, long a, long b) {
        Long pa = jdbc.queryForObject("SELECT list_position FROM person WHERE sheet = ? AND id = ?", Long.class, sheet, a);
        Long pb = jdbc.queryForObject("SELECT list_position FROM person WHERE sheet = ? AND id = ?", Long.class, sheet, b);
        jdbc.update("UPDATE person SET list_position = ? WHERE sheet = ? AND id = ?", pb, sheet, a);
        jdbc.update("UPDATE person SET list_position = ? WHERE sheet = ? AND id = ?", pa, sheet, b);
    }

    public Person find(String sheet, long id) {
        List<Person> found = query(sheet, "WHERE sheet = ? AND id = ?", sheet, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on the sheet with this name or alias, ignoring case; null when there is none. */
    public Person findByName(String sheet, String name) {
        List<Person> found = query(sheet, "WHERE sheet = ? AND name_key = LOWER(?)", sheet, name);
        if (found.isEmpty()) {
            found = query(sheet, "WHERE sheet = ? AND id IN (SELECT person_id FROM person_alias WHERE sheet = ?"
                    + " AND alias_key = LOWER(?))", sheet, sheet, name);
        }
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether someone on the sheet other than {@code except} has this name, ignoring case. */
    public boolean nameTaken(String sheet, String name, Long except) {
        Integer taken = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet = ? AND name_key = LOWER(?) AND (? IS NULL OR id <> ?)",
                Integer.class, sheet, name, except, except);
        return taken != null && taken > 0;
    }

    /** Adds the person with their first grade, which applies from the beginning of time. */
    public Person add(String sheet, String name, String grade) throws DuplicatePersonNameException {
        return add(sheet, name, grade, null, null);
    }

    /** Adds the person with their first grade, which applies from the beginning of time, their own terms and contact (null: none). */
    public Person add(String sheet, String name, String grade, Integer terms, String contact)
            throws DuplicatePersonNameException {
        if (nameTaken(sheet, name, null) || aliases.taken(sheet, name) || usedInTree(sheet, name)) {
            throw new DuplicatePersonNameException(name);
        }
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        try {
            insert(sheet, name, keys);
        } catch (DuplicateKeyException e) {
            throw new DuplicatePersonNameException(name);
        }
        long id = keys.getKey().longValue();
        setGrade(id, grade, null);
        setTerms(id, terms);
        setContact(id, contact);
        return find(sheet, id);
    }

    private void insert(String sheet, String name, GeneratedKeyHolder keys) {
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO person (sheet, name, list_position) VALUES (?, ?, "
                    + NEXT_POSITION + ")", new String[] { "id" });
            ps.setString(1, sheet);
            ps.setString(2, name);
            ps.setString(3, sheet);
            return ps;
        }, keys);
    }

    /** Records the person's grade from the from-date (null: from the beginning of time), replacing the one there for it. */
    public void setGrade(long id, String grade, LocalDate from) {
        Date date = from == null ? null : Date.valueOf(from);
        if (jdbc.update("UPDATE person_grade SET grade = ? WHERE person_id = ? AND from_date IS NOT DISTINCT FROM ?",
                grade, id, date) == 0) {
            jdbc.update("INSERT INTO person_grade (person_id, grade, from_date) VALUES (?, ?, ?)", id, grade, date);
        }
    }

    /** Sets the person's own terms (null: none). */
    public void setTerms(long id, Integer terms) {
        jdbc.update("UPDATE person SET terms = ? WHERE id = ?", terms, id);
    }

    /** Sets the person's contact (null: none). */
    public void setContact(long id, String contact) {
        jdbc.update("UPDATE person SET contact = ? WHERE id = ?", contact, id);
    }

    /** Sets the person's tags (lower-cased, sorted; empty: none). */
    public void setTags(long id, List<String> tags) {
        jdbc.update("UPDATE person SET tags = ? WHERE id = ?", String.join(",", tags), id);
    }

    /** Whether someone on the sheet other than {@code except} has this contact. */
    public boolean contactTaken(String sheet, String contact, Long except) {
        Integer taken = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet = ? AND contact = ? AND (? IS NULL OR id <> ?)",
                Integer.class, sheet, contact, except, except);
        return taken != null && taken > 0;
    }

    /** Retire the person from the date. */
    public void retire(String sheet, long id, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet = ? AND id = ?", Date.valueOf(from), sheet, id);
    }

    /** Unretire the person on the date, keeping the retirement from its from-date to that date as a past one. */
    public void unretire(String sheet, long id, LocalDate from, LocalDate on) {
        jdbc.update("INSERT INTO person_retirement (person_id, from_date, to_date) VALUES (?, ?, ?)", id,
                Date.valueOf(from), Date.valueOf(on));
        jdbc.update("UPDATE person SET retired_from = NULL WHERE sheet = ? AND id = ?", sheet, id);
    }

    /** Adds a hold to the person. */
    public void hold(long id, Hold hold) {
        jdbc.update("INSERT INTO person_hold (person_id, from_date, to_date) VALUES (?, ?, ?)", id,
                Date.valueOf(hold.from()), hold.to() == null ? null : Date.valueOf(hold.to()));
    }

    /** Save the person's name over the version it carries, raising the version; refused when it has moved on. */
    public void update(String sheet, Person person) throws DuplicatePersonNameException, StalePersonException {
        if (nameTaken(sheet, person.name(), person.id()) || aliases.taken(sheet, person.name())) {
            throw new DuplicatePersonNameException(person.name());
        }
        int updated;
        try {
            updated = jdbc.update(
                    "UPDATE person SET name = ?, version = version + 1 WHERE sheet = ? AND id = ? AND version = ?",
                    person.name(), sheet, person.id(), person.version());
        } catch (DuplicateKeyException e) {
            throw new DuplicatePersonNameException(person.name());
        }
        if (updated == 0) {
            throw new StalePersonException(person.id());
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.DatedValue;
import net.officefloor.hq.app.setting.Settings;

/**
 * What makes an overdue claim's late charge: the sheet's late percent (two decimals) by date, the one in force on each 30-day boundary after the claim's due-by, and its today; a claim is due
 * by the due-by fixed when it was added. The charge is never bound by a statement: it follows the sheet's today.
 * It also carries the sheet's policy date, which decides how a claim's live figures round, and each grade's grace
 * as recorded by from-date: the days a claim of a person whose grade in force on its date has a grace in force on
 * that date is given past its due-by before it is overdue.
 */
public record Late(Dated pct, LocalDate today, LocalDate policy, Map<String, List<DatedValue>> grace) {

    /**
     * How the claim's live figures round: half up when it rounds on a date (its own, or for a correction the date of
     * the claim it corrects) before the policy date, half to even on or after it.
     */
    public RoundingMode rounding(Claim claim) {
        return LocalDate.parse(claim.roundsOn()).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /**
     * The date the claim's overdue days are counted from: its due-by (fixed when it was added) plus the grace of the
     * grade (its person's in force on its date; null for none) in force on its date, if any.
     */
    public LocalDate graceBy(Claim claim, String grade) {
        LocalDate dueBy = LocalDate.parse(claim.dueBy());
        List<DatedValue> history = grade == null ? null : grace.get(grade);
        String days = history == null ? "" : Settings.on(history, LocalDate.parse(claim.date()));
        return days.isEmpty() ? dueBy : dueBy.plusDays(Integer.parseInt(days));
    }

    /** Whether the claim is overdue: OPEN or PENDING, not deferred, with its {@link #graceBy} before the sheet's today. */
    public boolean overdue(Claim claim, String grade) {
        return !claim.deferred() && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING) && graceBy(claim, grade).isBefore(today);
    }

    /**
     * The claim's late charge on its figure, compounding: for each full 30 days it is overdue, the late percent in force
     * on that boundary (its {@link #graceBy} plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries
     * before it, rounded in hundredths by the claim's {@link #rounding}, the charges added up (a boundary at 0.00 adds
     * nothing); 0.00 when it is not overdue, and always for a correction.
     */
    public BigDecimal charge(Claim claim, String grade, BigDecimal figure) {
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        if (figure == null || claim.correction() || !overdue(claim, grade)) {
            return total;
        }
        LocalDate dueBy = graceBy(claim, grade);
        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
        for (long k = 1; k <= periods; k++) {
            BigDecimal boundaryPct = pct.on(dueBy.plusDays(30 * k));
            if (boundaryPct.signum() != 0) {
                total = total.add(figure.add(total).multiply(boundaryPct).movePointLeft(2).setScale(2, rounding(claim)));
            }
        }
        return total;
    }
}
package net.officefloor.hq.app.claim;

/**
 * Where a claim is in its life: only OPEN, PENDING and SETTLED claims count toward the totals. A clerk's settle of a
 * due above the clerk limit makes it PENDING, which a steward approves (SETTLED) or rejects (back to OPEN). A steward
 * may void a SETTLED claim within 7 days of its settlement. A DRAFT may be DELETED (counting nowhere, not editable,
 * openable nor voidable), and restored to a DRAFT on the sheet-today it was deleted.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED;

    /** The status a change takes this claim to, or null when the change is not allowed from here. */
    public ClaimStatus after(ClaimStatusChange change) {
        return switch (change) {
            case OPEN -> this == DRAFT ? OPEN : null;
            case SETTLE -> this == OPEN ? SETTLED : null;
            case PEND -> this == OPEN ? PENDING : null;
            case APPROVE -> this == PENDING ? SETTLED : null;
            case REJECT -> this == PENDING ? OPEN : null;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED ? VOID : null;
            case DELETE -> this == DRAFT ? DELETED : null;
            case RESTORE -> this == DELETED ? DRAFT : null;
        };
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import java.time.LocalDate;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetArchive;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.hq.app.voidreason.VoidReasons;
import net.officefloor.hq.app.watch.Watches;
import org.springframework.stereotype.Service;

/** Moves a claim to the status a change takes it to, refusing a change its status does not allow; shared by a
 *  claim's own status buttons and the bulk actions. */
@Service
public class ClaimStatusChanger {

    /** How many days after its settlement a steward may still void a SETTLED claim. */
    public static final int VOID_SETTLED_DAYS = 7;

    private final Claims claims;
    private final People people;
    private final Rates rates;
    private final Periods periods;
    private final Roles roles;
    private final Settings settings;
    private final SheetClock clock;
    private final Audit audit;
    private final Rollup rollup;
    private final ClaimLog log;
    private final Watches watches;
    private final SheetArchive archive;
    private final VoidReasons voidReasons;

    public ClaimStatusChanger(Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
            SheetClock clock, Audit audit, Rollup rollup, ClaimLog log, Watches watches, SheetArchive archive,
            VoidReasons voidReasons) {
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.periods = periods;
        this.roles = roles;
        this.settings = settings;
        this.clock = clock;
        this.audit = audit;
        this.rollup = rollup;
        this.log = log;
        this.watches = watches;
        this.archive = archive;
        this.voidReasons = voidReasons;
    }

    /** Applies the change to the claim, writing nothing when it is refused. */
    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested)
            throws InvalidClaimStatusChangeException {
        change(sheet, user, claim, requested, null);
    }

    /** Applies the change to the claim (a reject gives its reason, a void the one chosen from the sheet's void reasons),
     *  writing nothing when it is refused. */
    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason)
            throws InvalidClaimStatusChangeException {
        requested = vet(sheet, user, claim, requested, reason);
        String voidReason = requested == ClaimStatusChange.VOID && voidReasons.any(sheet) ? reason.trim() : null;
        Person person = people.find(sheet, claim.person());
        Rollup.Snapshot before = rollup.take(sheet);
        ClaimStatus next = claim.status().after(requested);
        // Conditional on the status read, so a concurrent change by another user is refused, not overwritten.
        if (next == null || !claims.changeStatus(sheet, claim.id(), claim.status(), next)) {
            throw new InvalidClaimStatusChangeException(
                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
        }
        // Opening gives the next number (FY<yyyy>-<n>) of its fiscal year its sheet's tree shares, or, while the sheet numbers by period from on or
        // before its today, the next number in the claim's period (X for none); a voided claim keeps the number it
        // had (never reused).
        Claim changed = claim;
        if (requested == ClaimStatusChange.OPEN) {
            changed = number(sheet, claim);
            claims.setOpenedBy(sheet, claim.id(), user);
        }
        String fields = changed.statusAuditFields(person.name());
        // Settling (or approving a PENDING claim, its live figure then) fixes the due at the person's grade rate in force on the claim's date (or the figure its
        // statement bound), with its late charge frozen in; with no rate there is nothing to fix, so it stays live.
        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                    settings.late(sheet, clock.today(sheet)));
            claims.setSettledDue(sheet, claim.id(), due);
            fields += " due=" + (due == null ? "n/a" : due.toPlainString());
        }
        // Voiding a SETTLED claim reverses its frozen figure out of every total.
        if (requested == ClaimStatusChange.VOID && claim.status() == ClaimStatus.SETTLED) {
            fields += " reversed=" + (claim.settledDue() == null ? "n/a" : claim.settledDue());
        }
        if (requested == ClaimStatusChange.REJECT) {
            fields += " reason=" + reason.trim();
        }
        if (voidReason != null) {
            voidReasons.voided(sheet, claim.id(), voidReason);
            fields += " reason=" + voidReason;
        }
        log.record(sheet, user, claim.id());
        audit.record(requested.event() + " sheet=" + sheet + " by=" + user + " " + fields);
        // Settling or approving tells each user watching the person, before the rollup lines.
        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
            watches.notify(sheet, user, person.id(), person.name(), changed.shownNumber());
        }
        rollup.record(sheet, user, before);
    }

    /** Refuses the change the user may not make to the claim as it is now, writing nothing; otherwise gives the change
     *  it makes (a clerk's settle above the clerk limit is a move to PENDING). */
    public ClaimStatusChange vet(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason)
            throws InvalidClaimStatusChangeException {
        // A viewer changes nothing.
        if (Role.VIEWER.equals(roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("A viewer cannot change a claim");
        }
        if (archive.archived(sheet)) {
            throw new InvalidClaimStatusChangeException("An archived sheet cannot change");
        }
        // The permission matrix says which roles open, settle and void a claim.
        if ((requested == ClaimStatusChange.OPEN || requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.VOID)
                && !settings.permits(sheet, requested.name().toLowerCase(), roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Your role may not " + requested.name().toLowerCase() + " a claim");
        }
        if (periods.closedOn(sheet, LocalDate.parse(claim.dueBy()))) {
            throw new InvalidClaimStatusChangeException("A claim due inside a closed period cannot change status");
        }
        // A steward voids a SETTLED claim only within 7 days of its settlement (its status log's last SETTLED date).
        if (requested == ClaimStatusChange.VOID && claim.status() == ClaimStatus.SETTLED) {
            if (!Role.STEWARD.equals(roles.of(sheet, user))) {
                throw new InvalidClaimStatusChangeException("Only a steward voids a settled claim");
            }
            LocalDate settled = claim.settledOn();
            LocalDate today = clock.today(sheet);
            if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
                throw new InvalidClaimStatusChangeException(
                        "A settled claim may be voided only within " + VOID_SETTLED_DAYS + " days of its settlement");
            }
        }
        // A DELETED claim is restored only on the sheet's today it was deleted (its status log's last DELETED date).
        if (requested == ClaimStatusChange.RESTORE && claim.status() == ClaimStatus.DELETED
                && !clock.today(sheet).equals(claim.deletedOn())) {
            throw new InvalidClaimStatusChangeException("A deleted claim may be restored only on the day it was deleted");
        }
        if (requested == ClaimStatusChange.SETTLE && claim.deferred()) {
            throw new InvalidClaimStatusChangeException("A deferred claim cannot be settled until its date");
        }
        // Four eyes: the user who opened a claim may not settle it, nor approve it.
        if ((requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
                && user.equals(claim.openedBy())) {
            throw new InvalidClaimStatusChangeException("The user who opened a claim cannot settle or approve it");
        }
        // Nor may the user who last edited it.
        if ((requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
                && user.equals(claims.editedBy(sheet, claim.id()))) {
            throw new InvalidClaimStatusChangeException("The user who last edited a claim cannot settle or approve it");
        }
        // Only a steward approves or rejects a PENDING claim; a reject gives a reason.
        if ((requested == ClaimStatusChange.APPROVE || requested == ClaimStatusChange.REJECT)
                && !Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Only a steward approves or rejects a claim");
        }
        if (requested == ClaimStatusChange.REJECT && (reason == null || reason.isBlank())) {
            throw new InvalidClaimStatusChangeException("A reject needs a reason");
        }
        // While the sheet has void reasons, a void needs one chosen from them (with none, a void takes no reason).
        if (requested == ClaimStatusChange.VOID && voidReasons.any(sheet)) {
            String voidReason = reason == null ? "" : reason.trim();
            if (voidReason.isEmpty() || !voidReasons.has(sheet, voidReason)) {
                throw new InvalidClaimStatusChangeException("A void needs a reason from the sheet's void reasons");
            }
        }
        Person person = people.find(sheet, claim.person());
        // A claim whose due is above the proof threshold in force on its date (its person's grade's then when it has
        // one, else the sheet's) is settled or approved only once it has
        // a proof (a due of n/a is above no threshold); checked before the clerk limit, so it never goes to PENDING.
        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
            BigDecimal threshold = settings.proofThreshold(sheet, person.gradeOn(claim.date()),
                    LocalDate.parse(claim.date()));
            if (threshold != null && claim.proofs() == 0) {
                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                        settings.late(sheet, clock.today(sheet)));
                if (due != null && due.compareTo(threshold) > 0) {
                    throw new InvalidClaimStatusChangeException(
                            "A claim whose due is above the proof threshold needs a proof before it is settled or approved");
                }
            }
        }
        // A claim whose due is above the note threshold in force on its date is opened only with a note (a due of n/a
        // is above no threshold).
        if (requested == ClaimStatusChange.OPEN && (claim.note() == null || claim.note().isBlank())) {
            BigDecimal threshold = settings.noteThreshold(sheet, LocalDate.parse(claim.date()));
            if (threshold != null) {
                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                        settings.late(sheet, clock.today(sheet)));
                if (due != null && due.compareTo(threshold) > 0) {
                    throw new InvalidClaimStatusChangeException(
                            "A claim whose due is above the note threshold needs a note before it is opened");
                }
            }
        }
        // A clerk settles only a due at or below the sheet's clerk limit (a due of n/a is within any limit); above
        // it the claim goes to PENDING for a steward to approve. A steward settles anything.
        if (requested == ClaimStatusChange.SETTLE && claim.status() == ClaimStatus.OPEN
                && Role.CLERK.equals(roles.of(sheet, user))) {
            BigDecimal limit = settings.clerkLimit(sheet);
            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                    settings.late(sheet, clock.today(sheet)));
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                requested = ClaimStatusChange.PEND;
            }
        }
        if (claim.status().after(requested) == null) {
            throw new InvalidClaimStatusChangeException(
                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
        }
        // A period with a cap lets each person have at most that many OPEN or PENDING claims due inside it.
        if (requested == ClaimStatusChange.OPEN) {
            Period period = periods.on(sheet, LocalDate.parse(claim.dueBy()));
            if (period != null && period.cap() != null) {
                long held = claims.list(sheet).stream()
                        .filter((c) -> c.person() == claim.person() && c.id() != claim.id())
                        .filter((c) -> c.status() == ClaimStatus.OPEN || c.status() == ClaimStatus.PENDING)
                        .filter((c) -> c.dueBy().compareTo(period.from()) >= 0 && c.dueBy().compareTo(period.to()) <= 0)
                        .count();
                if (held >= period.cap()) {
                    throw new InvalidClaimStatusChangeException("A person may have at most " + period.cap()
                            + " open claims in period " + period.name());
                }
            }
        }
        return requested;
    }

    /**
     * Gives an opening claim the next number (FY<yyyy>-<n>) of its due-by's fiscal year in the sequence its sheet shares with its tree, or, while the sheet numbers by period from on or before its
     * today, the next number in the claim's period (X for none); returns the claim so numbered.
     */
    public Claim number(String sheet, Claim claim) {
        LocalDate from = settings.periodNumberingFrom(sheet);
        if (from != null && !clock.today(sheet).isBefore(from)) {
            String period = periods.nameOn(sheet, LocalDate.parse(claim.dueBy()));
            String key = period == null ? "" : period;
            Claim numbered = claim.withPeriodNumber((period == null ? "X" : period) + "-" + claims.nextPeriodNumber(sheet, key));
            claims.setPeriodNumber(sheet, claim.id(), numbered.periodNumber());
            return numbered;
        }
        // Sheet-wide numbering restarts each fiscal year (of the due-by, the date that places it in a period):
        // FY<yyyy>-<n>, kept as the number it shows.
        LocalDate dueBy = LocalDate.parse(claim.dueBy());
        int start = settings.fiscalStartMonth(sheet);
        String fy = "FY" + (dueBy.getMonthValue() >= start ? dueBy.getYear() : dueBy.getYear() - 1);
        Claim numbered = claim.withPeriodNumber(fy + "-" + claims.nextFiscalYearNumber(sheet, settings.wholeTree(sheet), fy));
        claims.setPeriodNumber(sheet, claim.id(), numbered.periodNumber());
        return numbered;
    }
