561	 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total, and the sheet's
562	 * claimed-total, due-total and overdue-total (the totals leave out the single highest and lowest person's figure when
563	 * three or more people have one). A change takes them before it writes, then {@link #record} audits the ones it moved: a ROLLUP line
564	 * per person whose figures changed (in list order, by position; a new person counts as changed), then a TOTALS
565	 * line when the sheet's totals changed, then an ALERT line per person whose due-total crossed above the sheet's alert
566	 * threshold (from at or below it, or no due-total), in list order.
567	 */
568	@Service
569	public class Rollup {
570	
571	    /**
572	     * A person's figures: claimed (two decimals), due-total (two decimals, or n/a) and overdue-total (the dues of
573	     * their counted overdue claims, two decimals).
574	     */
575	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
576	    }
577	
578	    /** The sheet's figures at one moment: per person id, in list order, and the totals. */
579	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
