589	    public Rollup(People people, Claims claims, Rates rates, SheetClock clock, Settings settings, Audit audit) {
590	        this.people = people;
591	        this.claims = claims;
592	        this.rates = rates;
593	        this.clock = clock;
594	        this.settings = settings;
595	        this.audit = audit;
596	    }
597	
598	    /** The sheet's figures now. */
599	    public Snapshot take(String sheet) {
600	        LocalDate today = clock.today(sheet);
601	        List<Rate> sheetRates = rates.list(sheet);
602	        Dated floor = settings.floor(sheet);
603	        BigDecimal cap = settings.cap(sheet);
604	        Late late = settings.late(sheet, today);
605	        List<Claim> all = claims.list(sheet);
606	        Map<Long, Figures> figures = new LinkedHashMap<>();
607	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
608	        List<BigDecimal> dueFigures = new ArrayList<>();
609	        List<BigDecimal> overdueFigures = new ArrayList<>();
610	        for (Person person : people.list(sheet)) {
611	            List<Claim> mine = all.stream().filter((c) -> c.person() == person.id() && person.counts(c)).toList();
612	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
613	            BigDecimal due = BigDecimal.ZERO.setScale(2);
614	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
615	            for (Claim claim : mine) {
616	                if (!claim.correction()) {
617	                    claimed = claimed.add(new BigDecimal(claim.amount()));
618	                }
619	                BigDecimal d = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
620	                due = d == null ? due : due.add(d);
621	                if (d != null && late.overdue(claim, person.gradeOn(claim.date()))) {
622	                    overdue = overdue.add(d);
623	                }
624	            }
625	            // n/a when the grade has no rate on the sheet's today, unless a claim has a figure apart from it.
626	            boolean na = Rate.on(sheetRates, person.grade(), today) == null
627	                    && mine.stream().noneMatch((c) -> person.figureApartFrom(c, today, sheetRates, floor));
628	            due = Settings.capped(due, cap);
629	            claimedTotal = claimedTotal.add(claimed);
630	            overdueFigures.add(overdue);
631	            if (!na) {
632	                dueFigures.add(due);
633	            }
634	            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), na ? "n/a" : due.toPlainString(),
635	                    overdue.toPlainString()));
636	        }
637	        return new Snapshot(figures, claimedTotal.toPlainString(), trimmedSum(dueFigures).toPlainString(),
638	                trimmedSum(overdueFigures).toPlainString());
639	    }
640	
641	    /** Adds up the people's figures, leaving out the single highest and the single lowest when three or more have one. */
642	    static BigDecimal trimmedSum(List<BigDecimal> figures) {
643	        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
644	        if (figures.size() < 3) {
645	            return sum;
646	        }
647	        return sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
648	    }
