650	    /** Audits the figures the change moved since {@code before}, after the change's own lines. */
651	    public void record(String sheet, String user, Snapshot before) {
652	        Snapshot after = take(sheet);
653	        String prefix = " sheet=" + sheet + " by=" + user + " ";
654	        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
655	            Figures now = entry.getValue();
656	            Figures was = before.people().get(entry.getKey());
657	            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
658	                    || !was.overdueTotal().equals(now.overdueTotal())) {
659	                audit.record("ROLLUP" + prefix + "person=" + now.name() + " claimed=" + now.claimed() + " due-total="
660	                        + now.dueTotal() + " overdue-total=" + now.overdueTotal());
661	            }
662	        }
663	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
664	                || !Objects.equals(before.dueTotal(), after.dueTotal())
665	                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
666	            audit.record("TOTALS" + prefix + "claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal()
667	                    + " overdue-total=" + after.overdueTotal());
668	        }
669	        BigDecimal threshold = settings.alertThreshold(sheet);
670	        if (threshold == null) {
671	            return;
672	        }
673	        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
674	            Figures now = entry.getValue();
675	            Figures was = before.people().get(entry.getKey());
676	            if (above(now, threshold) && (was == null || !above(was, threshold))) {
677	                audit.record("ALERT" + prefix + "name=" + now.name() + " due-total=" + now.dueTotal());
678	            }
679	        }
680	    }
