682	    /** Whether the person has a due-total above the threshold. */
683	    private static boolean above(Figures figures, BigDecimal threshold) {
684	        return !"n/a".equals(figures.dueTotal()) && new BigDecimal(figures.dueTotal()).compareTo(threshold) > 0;
685	    }
