116	
117	/** Whether a claim's statement binds its figure: it is stated and not PENDING (which shows its live figure). */
118	export function bound(claim: Claim): boolean {
119	  return claim.stated && claim.status !== 'PENDING';
120	}
121	
122	/** A claim: its amount with two decimals, its date (yyyy-MM-dd), its note, its status and its number on
123	 * the sheet (given when it is opened; null while a draft; kept once voided), and its due fixed when it was
124	 * settled (two decimals; null while live: until settled, and when its grade had no rate then), and the
125	 * user who opened it (null until opened; that user may not settle it), and whether its person's last statement
126	 * bound it, with the figure it bound (null when its grade had no rate then), and the number the claim it
127	 * corrects shows (null unless it is a correction: a negative amount), and the date it rounds on (its own, or for a
128	 * correction the date of the claim it corrects), and its number within its period (<period>-<n>, or X-<n> in no
129	 * period) when it was opened while the sheet numbered by period, shown in place of its number (null otherwise), and
130	 * its due-by (yyyy-MM-dd), fixed when it was added as the terms-th business day after its date (skipping weekends and holidays), from the terms of its person's grade in force on its date (worked out again with those terms when a holiday on or before it is added, unless SETTLED or VOID), and
131	 * its status log, oldest first, and the date it was last deferred until (null when never), with whether it is
132	 * deferred now (OPEN, or VOID when voided while deferred, with that date after the sheet's today: it counts in no total, is not overdue and cannot be
133	 * settled), and the number the claim it was split off shows (null unless it was split off one). */
134	export type Claim = {
135	  id: number;
136	  person: number;
137	  amount: string;
138	  date: string;
139	  note: string;
140	  status: ClaimStatus;
141	  number: number | null;
142	  settledDue: string | null;
143	  openedBy: string | null;
144	  stated: boolean;
145	  statedDue: string | null;
146	  corrects: string | null;
147	  roundsOn: string;
148	  periodNumber: string | null;
149	  dueBy: string;
150	  log: ClaimLogLine[];
151	  deferredUntil: string | null;
152	  deferred: boolean;
153	  /** How many proofs the claim has: one above the sheet's proof threshold needs one to be settled or approved. */
154	  proofs: number;
155	  splitFrom: string | null;
156	  /** The user whose open editor locks the claim against everyone else's edit button (null when none does). */
157	  lockedBy: string | null;
158	  /** Whether it was added while the period its due-by falls in was soft-closed. */
159	  lateEntry: boolean;
160	  /** The sheet's today it was last reminded on (null when never): an OPEN or PENDING claim is reminded once per day. */
161	  remindedOn: string | null;
162	  /** Its external reference, trimmed (null for none): no two claims on the sheet share one, ignoring case. */
163	  ref: string | null;
164	  /** Its tags: each trimmed and lower-cased, repeats dropped, sorted (a claim split off another carries its tags). */
165	  tags: string[];
166	  /** Every tag it has ever carried, sorted: the sheet lists a due-total for each tag any of its claims ever carried. */
167	  tagsEver: string[];
168	  /** The number of the bulk settle batch that last settled it (null when settled one at a time, or never). */
169	  batch: number | null;
170	  /** Its comments, in the order written. */
171	  comments: ClaimComment[];
172	  /** Its lines, in the order added: with any, its amount is their quantities times unit amounts added up. */
173	  lines: ClaimLine[];
174	};
175	
176	/** One line of a claim: its label, quantity (a whole number) and unit amount (two decimals). */
177	export type ClaimLine = { label: string; qty: number; unit: string };
178	
179	/** One comment on a claim: the user who wrote it, the sheet's today then (yyyy-MM-dd), and its text. */
180	export type ClaimComment = { by: string; on: string; text: string };
181	
182	/** One line of a claim's status log: the status it took, by whom, on the sheet's today then (yyyy-MM-dd), and the
183	 * claim's due as computed at that moment (two decimals, or n/a). */
184	export type ClaimLogLine = { status: ClaimStatus; by: string; on: string; due: string };
185	
186	export const claimsKey = (sheet: string) => ['claims', sheet] as const;
187	
188	export const claimsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/claims`;
189	
190	/** Every claim on the sheet, newest first. */
191	export function useClaims(sheet: string) {
192	  const read = useReadScope(claimsKey(sheet));
193	  return useQuery({
194	    queryKey: read.key,
195	    queryFn: () => read.get<Claim[]>(claimsPath(sheet)),
196	  });
197	}
198	
199	/** The claims that count toward claimed, due-total and every total: the OPEN, PENDING and SETTLED ones, but not
200	 *  the deferred ones, nor the OPEN or PENDING ones dated within a hold of their person or whose person's retirement
201	 *  date is reached, unless bound by a statement. */
202	export function counted(claims: Claim[], people: Person[]): Claim[] {
203	  const byId = new Map(people.map((p) => [p.id, p]));
204	  return claims.filter((c) => {
205	    if (c.deferred) return false;
206	    if (c.status === 'SETTLED') return true;
207	    if (!isOpen(c)) return false;
208	    const person = byId.get(c.person);
209	    return bound(c) || person === undefined || !setAsideOn(person, c.date);
210	  });
211	}
212	
213	/** The status a claim had at the end of the day (yyyy-MM-dd), as its status log records it (the last line on or before
214	 *  it); undefined when it was not yet added then. A claim kept from before the log (no lines) has its status now. */
215	export function statusOn(claim: Claim, end: string): ClaimStatus | undefined {
216	  if (claim.log.length === 0) return claim.status;
217	  let then: ClaimStatus | undefined;
218	  for (const line of claim.log) if (line.on <= end) then = line.status;
219	  return then;
220	}
221	
222	/** Whether a claim counts toward a period ending on the day (yyyy-MM-dd): by the status it had at the end of it
223	 *  (OPEN, PENDING or SETTLED; not yet added: no), unless deferred now, or open now (as {@link counted}), unbound and
224	 *  dated within a hold of its person or its person's retirement date is reached. */
225	export function countedOn(claim: Claim, person: Person | undefined, end: string): boolean {
226	  const then = statusOn(claim, end);
227	  if (claim.deferred || then === undefined) return false;
228	  if (then === 'SETTLED') return true;
229	  if (then !== 'OPEN' && then !== 'PENDING') return false;
230	  return !isOpen(claim) || bound(claim) || person === undefined || !setAsideOn(person, claim.date);
231	}
232	
233	/** The sum of the claims' amounts with two decimals, added in whole cents so no float error shows, leaving out the
234	 *  corrections (claims that correct another). */
235	export function claimed(claims: Claim[]): string {
236	  return twoDecimals(claims.reduce((sum, c) => (correction(c) ? sum : sum + hundredths(c.amount)), 0n));
237	}
238	
239	/** Whether a claim is a correction: a negative amount, correcting the settled claim it names by number. */
240	export function correction(claim: Claim): boolean {
241	  return claim.amount.startsWith('-');
242	}
243	
244	/** Whether a claim keeps its figure whatever the rates: fixed when settled, or bound by a statement (a claim
245	 *  settled or bound when its grade had no rate keeps none). */
246	export function fixed(claim: Claim): boolean {
247	  return claim.settledDue !== null || (bound(claim) && claim.statedDue !== null);
248	}
249	
250	/** What makes an overdue claim's late charge: the sheet's late percent (in hundredths) by date, the one in force on
251	 *  each 30-day boundary after the claim's due-by, and its today.
252	 *  The charge is never bound by a statement: it follows the sheet's today. It also carries the sheet's policy date
253	 *  (yyyy-MM-dd; undefined: its today), which decides how a claim's live figures round. And the date a claim's
254	 *  overdue days are counted from (yyyy-MM-dd): its due-by plus the grace of its person's grade in force on its date,
255	 *  where that grade has one in force on that date. */
256	export type Late = { pct: DatedCents; today: string | undefined; policy: string | undefined; graceBy: (claim: Claim) => string };
257	
258	/** The sheet's late percent, today, policy date and graces. */
259	export function useLate(sheet: string): Late {
260	  const today = useSheetToday(sheet);
261	  const policy = usePolicyDate(sheet);
262	  const grace = useGraceDays(sheet);
263	  const { data: people } = usePeople(sheet);
264	  const graceBy = (claim: Claim) => {
265	    const person = people?.find((p) => p.id === claim.person);
266	    const days = person === undefined ? 0 : grace(gradeOn(person, claim.date), claim.date);
267	    return days === 0 ? claim.dueBy : plusDays(claim.dueBy, days);
268	  };
269	  return { pct: useLatePctCents(sheet), today, policy: policy === '' ? today : policy, graceBy };
270	}
271	
272	/** Whether a claim's live figures round half up: it rounds on a date (its own, or for a correction the date of the
273	 *  claim it corrects) before the policy date; on or after it they round half to even. */
274	export function roundsHalfUp(claim: Claim, late: Late): boolean {
275	  return late.policy !== undefined && claim.roundsOn < late.policy;
276	}
277	
278	/** A claim's figure: the one fixed when it was settled, else the rate figure its statement bound, else its amount at the
279	 *  grade's rate in force on its date (in hundredths); the floor is applied last, in {@link claimDueCents}. */
280	export function claimFigureCents(claim: Claim, pct: string | undefined, floor: DatedCents, halfUp = false): bigint | undefined {
281	  if (claim.settledDue !== null) return hundredths(claim.settledDue);
282	  if (bound(claim)) return claim.statedDue === null ? undefined : hundredths(claim.statedDue);
283	  return dueCents(claim.amount, pct, halfUp);
284	}
285	
286	/** The whole days a claim is overdue: from its due-by plus its grace to the sheet's today (0 when it is not overdue). */
287	function daysOverdue(claim: Claim, late: Late): number {
288	  if (!overdue(claim, late)) return 0;
289	  return Math.round((Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${late.graceBy(claim)}T00:00:00Z`)) / 86_400_000);
290	}
291	
292	/** The day (yyyy-MM-dd) the given number of days after a day. */
293	function plusDays(day: string, days: number): string {
294	  return new Date(Date.parse(`${day}T00:00:00Z`) + days * 86_400_000).toISOString().slice(0, 10);
295	}
296	
297	/** A claim's late charge on its figure (in hundredths), compounding: for each full 30 days it is overdue, the late
298	 *  percent in force on that boundary (its due-by plus its grace plus 30, 60, 90 ... days) of the figure plus the
299	 *  charges of the boundaries before it, rounded as the claim's live figures
300	 *  are (see {@link roundsHalfUp}), the charges added up; a correction has none. */
301	export function lateCents(claim: Claim, figure: bigint, late: Late): bigint {
302	  if (correction(claim)) return 0n;
303	  const periods = Math.floor(daysOverdue(claim, late) / 30);
304	  let total = 0n;
305	  for (let k = 1; k <= periods; k++) {
306	    const pct = late.pct(plusDays(late.graceBy(claim), 30 * k));
307	    if (pct === 0n) continue;
308	    const product = (figure + total) * pct;
309	    const quotient = product / 10000n;
310	    const remainder = product % 10000n;
311	    const up = remainder > 5000n || (remainder === 5000n && (roundsHalfUp(claim, late) || quotient % 2n === 1n));
312	    total += up ? quotient + 1n : quotient;
313	  }
314	  return total;
315	}
316	
317	/** A claim's due: the one fixed when settled; else the greater of the sheet's floor in force on its date and its
318	 *  figure plus, while it is overdue, its late charge on that figure (a correction has no floor and no charge). */
319	export function claimDueCents(claim: Claim, pct: string | undefined, floor: DatedCents, late: Late): bigint | undefined {
320	  const figure = claimFigureCents(claim, pct, floor, roundsHalfUp(claim, late));
321	  if (figure === undefined || claim.settledDue !== null || correction(claim)) return figure;
322	  const charged = figure + lateCents(claim, figure, late);
323	  const least = floor(claim.date);
324	  return charged >= least ? charged : least;
325	}
326	
327	
328	/** A person's due-total: the sum of their counted claims' rounded figures (the claims of others are skipped). n/a (undefined) when their grade
329	 *  has no rate on the sheet's today, unless a claim has a figure apart from it (settled, stated, at another grade
330	 *  in force on its date, or from a rate that ended by today on a claim not dated after it): then the figures there are.
331	 *  With a cap, a due-total above it is the cap (an n/a one is not capped). */
332	export function personDueCents(
333	  claims: Claim[],
334	  rates: Rate[],
335	  person: Person,
336	  today: string | undefined,
337	  floor: DatedCents,
338	  late: Late,
339	  cap?: bigint,
340	): bigint | undefined {
341	  const sum = uncappedPersonDueCents(claims, rates, person, today, floor, late);
342	  return sum !== undefined && cap !== undefined && sum > cap ? cap : sum;
343	}
344	
345	/** A person's due-total before the cap: the sum of their figures (see {@link personDueCents}). */
346	export function uncappedPersonDueCents(
347	  claims: Claim[],
348	  rates: Rate[],
349	  person: Person,
350	  today: string | undefined,
351	  floor: DatedCents,
352	  late: Late,
353	): bigint | undefined {
354	  const mine = counted(claims.filter((c) => c.person === person.id), [person]);
355	  // A claim has a figure apart from today's grade when it keeps one, or when another grade in force on its date gives one.
356	  const apart = (c: Claim) => {
357	    const then = gradeOn(person, c.date);
358	    return fixed(c) || (then !== undefined && then !== person.grade && claimFigureCents(c, rateOf(rates, then, c.date), floor) !== undefined)
359	      || (then !== undefined && today !== undefined && c.date <= today && claimFigureCents(c, rateOf(rates, then, c.date), floor) !== undefined);
360	  };
361	  if (rateOf(rates, person.grade, today) === undefined && !mine.some(apart)) return undefined;
362	  return mine.reduce((sum, c) => sum + (claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n), 0n);
363	}
364	
365	/** A person's settled-total and open-total (in hundredths): the dues of their SETTLED claims that count (at their
366	 *  frozen figures, corrections included) and of their OPEN and PENDING ones that count (see {@link counted}). Together
367	 *  they make the due-total before the cap; a claim with no due adds nothing. */
368	export function splitDueCents(
369	  claims: Claim[],
370	  rates: Rate[],
371	  person: Person,
372	  floor: DatedCents,
373	  late: Late,
374	): { settled: bigint; open: bigint } {
375	  const split = { settled: 0n, open: 0n };
376	  for (const c of counted(claims.filter((c) => c.person === person.id), [person])) {
377	    const due = claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n;
378	    if (c.status === 'SETTLED') split.settled += due;
379	    else if (isOpen(c)) split.open += due;
380	  }
381	  return split;
382	}
383	
384	/** A person's recent settled figure: the sum of their SETTLED claims' frozen figures dated within the 90 days up to
385	 *  and including the sheet's today (today and the 89 days before it); a claim settled with no figure adds nothing. */
386	export function recentSettledCents(claims: Claim[], person: Person, today: string | undefined): bigint {
387	  if (today === undefined) return 0n;
388	  const since = plusDays(today, -89);
389	  return claims
390	    .filter((c) => c.person === person.id && c.status === 'SETTLED' && c.date >= since && c.date <= today)
391	    .reduce((sum, c) => sum + (c.settledDue === null ? 0n : hundredths(c.settledDue)), 0n);
392	}
393	
394	/** Whether a person is active: they have an OPEN or PENDING claim that counts (see {@link counted}) dated within the
395	 *  30 days up to and including the sheet's today (today and the 29 days before it). */
396	export function isActive(claims: Claim[], person: Person, today: string | undefined): boolean {
397	  if (today === undefined) return false;
398	  const since = plusDays(today, -29);
399	  return counted(claims.filter((c) => c.person === person.id), [person]).some(
400	    (c) => isOpen(c) && c.date >= since && c.date <= today,
401	  );
402	}
403	
404	/** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by plus its grace before the sheet's today. */
405	export function overdue(claim: Claim, late: Late): boolean {
406	  return isOpen(claim) && !claim.deferred && late.today !== undefined && late.graceBy(claim) < late.today;
407	}
408	
409	/** The overdue claims that count (see {@link counted}) among a person's or the sheet's claims, and the sum of
410	 *  their dues (in hundredths; a claim with no due adds nothing). */
411	export function overdueCents(
412	  claims: Claim[],
413	  people: Person[],
414	  rates: Rate[],
415	  late: Late,
416	  floor: DatedCents,
417	): { count: number; cents: bigint } {
418	  const byId = new Map(people.map((p) => [p.id, p]));
419	  const overdueClaims = counted(claims, people).filter((c) => byId.has(c.person) && overdue(c, late));
420	  const cents = overdueClaims.reduce(
421	    (sum, c) => sum + (claimDueCents(c, rateOf(rates, gradeOn(byId.get(c.person)!, c.date), c.date), floor, late) ?? 0n),
422	    0n,
423	  );
424	  return { count: overdueClaims.length, cents };
425	}
426	
427	/** A person's dues by the age of the claim on the sheet's today (the whole days from its date): their OPEN and
428	 *  PENDING claims that count (see {@link counted}) aged 0 to 30 days, 31 to 60, and 61 or more (in hundredths; a
429	 *  claim dated after today is 0 to 30, and a claim with no due adds nothing). */
430	export function agedCents(
431	  claims: Claim[],
432	  person: Person,
433	  rates: Rate[],
434	  late: Late,
435	  floor: DatedCents,
436	): { upTo30: bigint; upTo60: bigint; over60: bigint } {
437	  const aged = { upTo30: 0n, upTo60: 0n, over60: 0n };
438	  const today = late.today;
439	  for (const c of counted(claims.filter((c) => c.person === person.id), [person])) {
440	    if (!isOpen(c)) continue;
441	    const due = claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n;
442	    const days =
443	      today === undefined ? 0 : Math.round((Date.parse(`${today}T00:00:00Z`) - Date.parse(`${c.date}T00:00:00Z`)) / 86_400_000);
444	    if (days <= 30) aged.upTo30 += due;
445	    else if (days <= 60) aged.upTo60 += due;
446	    else aged.over60 += due;
447	  }
448	  return aged;
449	}
450	
451	/** Adds up the people's figures, leaving out the single highest and the single lowest when three or more people
452	 *  have a figure. */
453	export function trimmedSum(figures: bigint[]): bigint {
454	  const sum = figures.reduce((s, f) => s + f, 0n);
455	  if (figures.length < 3) return sum;
456	  const max = figures.reduce((m, f) => (f > m ? f : m));
457	  const min = figures.reduce((m, f) => (f < m ? f : m));
458	  return sum - max - min;
459	}
460	
461	/** The sheet's totals: its claimed-total (everyone's counted claims added up,
462	 *  corrections left out), its due-total (everyone's due-total
463	 *  added up, skipping the people whose due-total is n/a, trimmed — see trimmedSum), and how many of the counted claims
464	 *  are overdue, with their total (each person's overdue-total, trimmed), and its settled-total and open-total. */
465	export function useSheetTotals(sheet: string): {
466	  claimed: string;
467	  due: bigint;
468	  overdue: { count: number; cents: bigint };
469	  settled: bigint;
470	  open: bigint;
471	} {
472	  const { data: all = [] } = useClaims(sheet);
473	  const { data: people = [] } = usePeople(sheet);
474	  const { data: rates = [] } = useRates(sheet);
475	  const today = useSheetToday(sheet);
476	  const floor = useFloorCents(sheet);
477	  const late = useLate(sheet);
478	  const cap = useCapCents(sheet);
479	  const due = trimmedSum(
480	    people
481	      .map((p) => personDueCents(all, rates, p, today, floor, late, cap))
482	      .filter((cents): cents is bigint => cents !== undefined),
483	  );
484	  const overdue = overdueCents(all, people, rates, late, floor);
485	  const perPerson = people.map((p) => overdueCents(all, [p], rates, late, floor).cents);
486	  // The settled-total and open-total: everyone's added up, not trimmed.
487	  const split = people.map((p) => splitDueCents(all, rates, p, floor, late));
488	  return {
489	    claimed: claimed(counted(all, people)),
490	    due,
491	    overdue: { count: overdue.count, cents: trimmedSum(perPerson) },
492	    settled: split.reduce((s, x) => s + x.settled, 0n),
493	    open: split.reduce((s, x) => s + x.open, 0n),
494	  };
495	}
496	
497	/** Every tag ever carried by a claim on the sheet (`gone`: by claims since gone from it), or carried by a person on it,
498	 *  sorted. */
499	export function sheetTags(claims: Claim[], people: Person[] = [], gone: string[] = []): string[] {
500	  return [
501	    ...new Set([...claims.flatMap((c) => [...c.tagsEver, ...c.tags]), ...people.flatMap((p) => p.tags), ...gone]),
502	  ].sort();
503	}
504	
505	/** The due-total of each tag ever used on the sheet (in hundredths): the dues of the claims that count (see
506	 *  {@link counted}) which carry it or whose person carries it, once each; a claim with two tags counting in both;
507	 *  a claim with no due adds nothing. */
508	export function useTagDueTotals(sheet: string): { tag: string; cents: bigint }[] {
509	  const { data: all = [] } = useClaims(sheet);
510	  const { data: people = [] } = usePeople(sheet);
511	  const { data: rates = [] } = useRates(sheet);
512	  const floor = useFloorCents(sheet);
513	  const late = useLate(sheet);
514	  const { data: shown } = useSheet(sheet);
515	  const byId = new Map(people.map((p) => [p.id, p]));
516	  const totals = new Map(sheetTags(all, people, shown?.tagsGone).map((t) => [t, 0n]));
517	  for (const c of counted(all, people)) {
518	    const person = byId.get(c.person);
519	    if (person === undefined) continue;
520	    const tags = new Set([...c.tags, ...person.tags]);
521	    if (tags.size === 0) continue;
522	    const due = claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n;
523	    for (const t of tags) totals.set(t, (totals.get(t) ?? 0n) + due);
524	  }
525	  return [...totals].map(([tag, cents]) => ({ tag, cents }));
526	}
527	
528	/** The due-total of each calendar month (yyyy-mm) any claim on the sheet is dated in, sorted (in hundredths): the dues
529	 *  of the claims that count (see {@link counted}) dated in it; a claim with no due adds nothing. */
530	export function useMonthDueTotals(sheet: string): { month: string; cents: bigint }[] {
531	  const { data: all = [] } = useClaims(sheet);
532	  const { data: people = [] } = usePeople(sheet);
533	  const { data: rates = [] } = useRates(sheet);
534	  const floor = useFloorCents(sheet);
535	  const late = useLate(sheet);
536	  const byId = new Map(people.map((p) => [p.id, p]));
537	  const totals = new Map([...new Set(all.map((c) => c.date.slice(0, 7)))].sort().map((m) => [m, 0n]));
538	  for (const c of counted(all, people)) {
539	    const person = byId.get(c.person);
540	    if (person === undefined) continue;
541	    const due = claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n;
542	    const month = c.date.slice(0, 7);
543	    totals.set(month, (totals.get(month) ?? 0n) + due);
544	  }
545	  return [...totals].map(([month, cents]) => ({ month, cents }));
546	}
547	
548	/** Each person's due-total as their row shows it (see {@link personDueCents}): undefined when n/a. */
549	export function usePersonDueCentsOf(sheet: string): (person: Person) => bigint | undefined {
