758	// A person's claimed total, then their claims (newest first) under one form that adds a claim or,
759	// once a claim's editor is opened, edits it. A blank date takes the sheet's today on the server.
760	function PersonClaims({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
761	  const queryClient = useQueryClient();
762	  const { data: all = [] } = useClaims(sheet);
763	  const claims = all.filter((c) => c.person === person.id);
764	  const { data: rates = [] } = useRates(sheet);
765	  const floor = useFloorCents(sheet);
766	  const cap = useCapCents(sheet);
767	  const today = useSheetToday(sheet);
768	  const late = useLate(sheet);
769	  // The excess: how far the sum of their figures is above the cap (0.00 when it is not, or is n/a).
770	  const uncapped = uncappedPersonDueCents(claims, rates, person, today, floor, late);
771	  const excess = uncapped !== undefined && cap !== undefined && uncapped > cap ? uncapped - cap : 0n;
772	  const lateClaims = overdueCents(claims, [person], rates, late, floor);
773	  const aged = agedCents(claims, person, rates, late, floor);
774	  const split = splitDueCents(claims, rates, person, floor, late);
775	  const [draft, setDraft] = useState<Draft>(EMPTY);
776	  // The editor is open on the claim this user's lock holds, as the store says: it stays open across a re-load of the
777	  // sheet, and closes once the lock is released (saved, cancelled, or the sheet's today changed).
778	  const locked = claims.find((c) => c.lockedBy === user);
779	  const editing = locked?.id ?? null;
780	  const save = useMutation({
781	    mutationFn: ({ id, body }: { id: number | null; body: Draft }) =>
782	      id === null
783	        ? postJson<Claim[]>(byUser(`${peoplePath(sheet)}/${person.id}/claims`, user), body)
784	        : putJson<Claim[]>(byUser(`${claimsPath(sheet)}/${id}`, user), body),
785	    onSuccess: (updated) => {
786	      queryClient.setQueryData(claimsKey(sheet), updated);
787	      setDraft(EMPTY);
788	    },
789	  });
790	  const send = useSubmitOnce(save);
791	  // A DRAFT claim from a template: its amount and note as they are now, dated like a claim with no date; refused,
792	  // like the form, through claim-form-error.
793	  const { data: templates = [] } = useTemplates(sheet);
794	  const [template, setTemplate] = useState('');
795	  const fromTemplate = useMutation({
796	    mutationFn: (name: string) =>
797	      postJson<Claim[]>(byUser(`${peoplePath(sheet)}/${person.id}/claims/template`, user), { template: name }),
798	    onSuccess: (updated) => queryClient.setQueryData(claimsKey(sheet), updated),
799	  });
800	  const sendFromTemplate = useSubmitOnce(fromTemplate);
801	  const addFromTemplate = () => {
802	    save.reset();
803	    sendFromTemplate(template);
804	  };
805	
806	  const filled = useRef<number | null>(null);
807	  useEffect(() => {
808	    if (filled.current === editing) return;
809	    filled.current = editing;
810	    setDraft(
811	      locked === undefined
812	        ? EMPTY
813	        : { amount: locked.amount, date: locked.date, note: locked.note, corrects: locked.corrects ?? '', ref: locked.ref ?? '', tags: locked.tags.join(', ') },
814	    );
815	    save.reset();
816	    // Only a move to another claim (or none) refills the form; the draft typed meanwhile is the user's.
817	    // eslint-disable-next-line react-hooks/exhaustive-deps
818	  }, [editing]);
819	
820	  const change = (next: Partial<Draft>) => {
821	    setDraft((d) => ({ ...d, ...next }));
822	    save.reset();
823	    fromTemplate.reset();
824	  };
825	
826	  // Cancel releases this user's lock; the form goes back to adding once the claims show it released.
827	  const unlock = useMutation({
828	    mutationFn: (id: number) => postJson<Claim[]>(byUser(`${claimsPath(sheet)}/${id}/unlock`, user), {}),
829	    onSuccess: (updated) => queryClient.setQueryData(claimsKey(sheet), updated),
830	  });
831	  const cancel = () => {
832	    save.reset();
833	    fromTemplate.reset();
834	    if (editing !== null) unlock.mutate(editing);
835	  };
836	
837	  const submit = (e: FormEvent) => {
838	    e.preventDefault();
839	    // The server refuses an amount that is not a number with up to two decimals, a bad date, or a negative amount
840	    // (a correction) that does not name a SETTLED claim of this person by number, or a
841	    // reference already used on the sheet (ignoring case).
842	    fromTemplate.reset();
843	    send({ id: editing, body: draft });
844	  };
845	
846	  return (
847	    <>
848	      <td data-testid="person-claimed">{claimed(counted(claims, [person]))}</td>
849	      <td data-testid="person-due-total">{showDue(personDueCents(claims, rates, person, today, floor, late, cap))}</td>
850	      <td data-testid="person-excess">{twoDecimals(excess)}</td>
851	      <td data-testid="person-overdue-count">{lateClaims.count}</td>
852	      <td data-testid="person-overdue-total">{twoDecimals(lateClaims.cents)}</td>
853	      <td data-testid="person-aged-0-30">{twoDecimals(aged.upTo30)}</td>
854	      <td data-testid="person-aged-31-60">{twoDecimals(aged.upTo60)}</td>
855	      <td data-testid="person-aged-61">{twoDecimals(aged.over60)}</td>
856	      <td data-testid="person-settled-total">{twoDecimals(split.settled)}</td>
857	      <td data-testid="person-open-total">{twoDecimals(split.open)}</td>
858	      <td>
859	        <form onSubmit={submit}>
860	          <input
861	            data-testid="claim-form-amount"
862	            placeholder="amount"
863	            value={draft.amount}
864	            onChange={(e) => change({ amount: e.target.value })}
865	          />{' '}
866	          <input
867	            data-testid="claim-form-date"
868	            placeholder="yyyy-mm-dd"
869	            value={draft.date}
870	            onChange={(e) => change({ date: e.target.value })}
871	          />{' '}
872	          <input
873	            data-testid="claim-form-note"
874	            placeholder="note"
875	            value={draft.note}
876	            onChange={(e) => change({ note: e.target.value })}
877	          />{' '}
878	          <input
879	            data-testid="claim-form-corrects"
880	            placeholder="corrects #"
881	            value={draft.corrects}
882	            onChange={(e) => change({ corrects: e.target.value })}
883	          />{' '}
884	          <input
885	            data-testid="claim-form-ref"
886	            placeholder="reference"
887	            value={draft.ref}
888	            onChange={(e) => change({ ref: e.target.value })}
889	          />{' '}
890	          <input
891	            data-testid="claim-form-tags"
892	            placeholder="tags, comma separated"
893	            value={draft.tags}
894	            onChange={(e) => change({ tags: e.target.value })}
895	          />{' '}
896	          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
897	            {editing === null ? 'Add claim' : 'Save claim'}
898	          </button>
899	          <select
900	            data-testid="claim-template-select"
901	            value={template}
902	            onChange={(e) => {
903	              setTemplate(e.target.value);
904	              fromTemplate.reset();
905	            }}
906	          >
907	            <option value="">template…</option>
908	            {templates.map((t) => (
909	              <option key={t.name} value={t.name}>
910	                {t.name}
911	              </option>
912	            ))}
913	          </select>{' '}
914	          <button type="button" data-testid="claim-template-add" disabled={fromTemplate.isPending} onClick={addFromTemplate}>
915	            Add from template
916	          </button>
917	          {(save.isError || fromTemplate.isError) && (
918	            <span data-testid="claim-form-error" role="alert">
919	              {' '}A claim needs an amount with up to two decimals, and a valid date not after the person's retirement date; a negative amount is a correction and must name, by number, a SETTLED claim of this person; a reference may not be one already used on the sheet; only a DRAFT claim can be edited; a claim from a template needs one of the sheet's templates chosen.
920	            </span>
921	          )}
922	        </form>
923	        <ul>
924	          {claims.map((c) => (
925	            <ClaimRow
926	              key={c.id}
927	              sheet={sheet}
928	              user={user}
929	              claim={c}
930	              rates={rates}
931	              grade={gradeOn(person, c.date)}
932	              editing={editing === c.id}
933	              onCancel={cancel}
934	            />
935	          ))}
936	        </ul>
937	      </td>
938	    </>
939	  );
