5	/** A grade's rate: a percent with two decimals, in force from its from-date (yyyy-MM-dd; null when it
6	 *  applies from the beginning of time) through its to-date (null when it has no end). Its level is the sheet it is
7	 *  kept on: 0 this sheet's own, 1 its parent's, 2 its parent's parent, up to {@link RATE_LEVELS}. */
8	export type Rate = { grade: Grade; pct: string; from: string | null; to: string | null; level: number };
9	
10	/** The most levels up a sheet's parents give it rates. */
11	export const RATE_LEVELS = 3;
12	
13	export const ratesKey = (sheet: string) => ['rates', sheet] as const;
14	
15	export const ratesPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/rates`;
16	
17	/** What a candidate rate for a grade would do: how many OPEN and PENDING claims would show a different due, and the
18	 *  sum of the differences (new due minus current due, two decimals; negative when lower). */
19	export type RatePreview = { count: number; diff: string };
20	
21	export const ratePreviewPath = (sheet: string, grade: Grade, pct: string) =>
22	  `${ratesPath(sheet)}/preview?grade=${encodeURIComponent(grade)}&pct=${encodeURIComponent(pct)}`;
23	
24	/** Every rate on the sheet, its own by grade then from-date (the one with none first), then its parents' by level;
25	 *  a grade with no rate is absent. */
26	export function useRates(sheet: string) {
27	  const read = useReadScope(ratesKey(sheet));
28	  return useQuery({
29	    queryKey: read.key,
30	    queryFn: () => read.get<Rate[]>(ratesPath(sheet)),
31	  });
32	}
33	
34	/** The rate for a grade on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it, or
35	 *  undefined when the date is before every rate the grade has, or after the to-date of that one (or the date
36	 *  is not yet known). When the sheet's own rates give none, the next level up is used. */
37	export function rateOf(rates: Rate[], grade: Grade | undefined, date: string | undefined): string | undefined {
38	  if (date === undefined || grade === undefined) return undefined;
39	  for (let level = 0; level <= RATE_LEVELS; level++) {
40	    const pct = rateAt(rates, grade, date, level);
41	    if (pct !== undefined) return pct;
42	  }
43	  return undefined;
44	}
45	
46	function rateAt(rates: Rate[], grade: Grade, date: string, level: number): string | undefined {
47	  let found: Rate | undefined;
48	  for (const r of rates) {
49	    if (r.grade !== grade || (r.level ?? 0) !== level || (r.from !== null && r.from > date)) continue;
50	    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
51	  }
52	  if (found?.to != null && found.to < date) return undefined;
53	  return found?.pct;
54	}
