56	/** A two-decimal string as a whole number of hundredths. */
57	export function hundredths(value: string): bigint {
58	  const negative = value.startsWith('-');
59	  const [whole, frac = ''] = value.replace(/^-/, '').split('.');
60	  const cents = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0').slice(0, 2));
61	  return negative ? -cents : cents;
62	}
63	
64	/** A whole number of hundredths as a two-decimal string. */
65	export function twoDecimals(cents: bigint): string {
66	  const abs = cents < 0n ? -cents : cents;
67	  return `${cents < 0n ? '-' : ''}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
68	}
69	
70	/** An amount times a percent, divided by 100, in hundredths rounded half to even (1.025 -> 1.02,
71	 *  1.035 -> 1.04), or half up when `halfUp` (1.025 -> 1.03); undefined when there is no rate. Worked in whole
72	 *  numbers so no float error shows. */
73	export function dueCents(amount: string, pct: string | undefined, halfUp = false): bigint | undefined {
74	  if (pct === undefined) return undefined;
75	  const product = hundredths(amount) * hundredths(pct);
76	  // Rounded on the magnitude, so a negative amount (a correction) rounds as its positive would.
77	  const abs = product < 0n ? -product : product;
78	  let quotient = abs / 10000n;
79	  const remainder = abs % 10000n;
80	  if (remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n))) quotient += 1n;
81	  return product < 0n ? -quotient : quotient;
82	}
83	
84	/** A due as the screen shows it: two decimals, or n/a when there is no rate. */
85	export function showDue(cents: bigint | undefined): string {
86	  return cents === undefined ? 'n/a' : twoDecimals(cents);
87	}
