143	/** Each grade's grace by date: the value of the latest from-date on or before it (a blank, or none: no grace). */
144	export function useGraceDays(sheet: string): GraceDays {
145	  const { data } = useSettings(sheet);
146	  return (grade, date) => {
147	    const entry = GRADE_GRACE.find((g) => g.grade === grade);
148	    if (entry === undefined) return 0;
149	    const sorted = [...(data?.dated?.[entry.key] ?? [])].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
150	    let value = '';
151	    for (const v of sorted) {
152	      if (v.from > date) break;
153	      value = v.value;
154	    }
155	    return value === '' ? 0 : Number.parseInt(value, 10);
156	  };
157	}
