 43	    /** Merges the person into the one with id {@code intoId}, writing nothing when it is refused. */
 44	    public void merge(String sheet, String user, Person from, Long intoId) throws InvalidPersonException {
 45	        if (!Role.STEWARD.equals(roles.of(sheet, user))) {
 46	            throw new InvalidPersonException("Only a steward may merge people");
 47	        }
 48	        Person into = intoId == null ? null : people.find(sheet, intoId);
 49	        if (into == null || into.id() == from.id()) {
 50	            throw new InvalidPersonException("A person is merged into another person on the sheet");
 51	        }
 52	        if (from.retiredFrom() != null || into.retiredFrom() != null) {
 53	            throw new InvalidPersonException("A retired person cannot be merged");
 54	        }
 55	        Rollup.Snapshot before = rollup.take(sheet);
 56	        long f = from.id();
 57	        long t = into.id();
 58	
 59	        // Claims, in the order they were added, each listed as the sheet's newest so they follow the other's.
 60	        for (Long claim : jdbc.queryForList("SELECT id FROM claim WHERE sheet = ? AND person = ? ORDER BY id",
 61	                Long.class, sheet, f)) {
 62	            jdbc.update("UPDATE claim SET person = ?, listed ="
 63	                    + " (SELECT COALESCE(MAX(l.listed), 0) + 1 FROM claim l WHERE l.sheet = ?) WHERE sheet = ? AND id = ?",
 64	                    t, sheet, sheet, claim);
 65	        }
 66	
 67	        // Name and aliases become the other's aliases.
 68	        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet = ? AND person_id = ?", t, sheet, f);
 69	        jdbc.update("INSERT INTO person_alias (sheet, person_id, alias) VALUES (?, ?, ?)", sheet, t, from.name());
 70	
 71	        // Patrons: the merged person's own, then everyone naming them.
 72	        for (Long patron : jdbc.queryForList("SELECT patron_id FROM patron WHERE sheet = ? AND person_id = ?",
 73	                Long.class, sheet, f)) {
 74	            addPatron(sheet, t, patron);
 75	        }
 76	        for (Long person : jdbc.queryForList("SELECT person_id FROM patron WHERE sheet = ? AND patron_id = ?",
 77	                Long.class, sheet, f)) {
 78	            addPatron(sheet, person, t);
 79	        }
 80	        jdbc.update("DELETE FROM patron WHERE sheet = ? AND (person_id = ? OR patron_id = ?)", sheet, f, f);
 81	
 82	        // Pool memberships, shares added where the other is already a member.
 83	        for (Map<String, Object> m : jdbc.queryForList(
 84	                "SELECT pool, share FROM pool_member WHERE sheet = ? AND person_id = ?", sheet, f)) {
 85	            String pool = (String) m.get("POOL");
 86	            BigDecimal share = (BigDecimal) m.get("SHARE");
 87	            if (jdbc.update("UPDATE pool_member SET share = share + ? WHERE sheet = ? AND pool = ? AND person_id = ?",
 88	                    share, sheet, pool, t) == 0) {
 89	                jdbc.update("UPDATE pool_member SET person_id = ? WHERE sheet = ? AND pool = ? AND person_id = ?", t,
 90	                        sheet, pool, f);
 91	            }
 92	        }
 93	        jdbc.update("DELETE FROM pool_member WHERE sheet = ? AND person_id = ?", sheet, f);
 94	
 95	        // Closed periods' totals follow the claims.
 96	        for (Map<String, Object> p : jdbc.queryForList(
 97	                "SELECT period, total FROM period_person_total WHERE sheet = ? AND person = ?", sheet, f)) {
 98	            String period = (String) p.get("PERIOD");
 99	            BigDecimal total = (BigDecimal) p.get("TOTAL");
100	            if (jdbc.update("UPDATE period_person_total SET total = total + ? WHERE sheet = ? AND period = ? AND person = ?",
101	                    total, sheet, period, t) == 0) {
102	                jdbc.update("UPDATE period_person_total SET person = ? WHERE sheet = ? AND period = ? AND person = ?",
103	                        t, sheet, period, f);
104	            }
105	        }
106	        jdbc.update("DELETE FROM period_person_total WHERE sheet = ? AND person = ?", sheet, f);
107	
108	        // Statements count as the other's, the other's last staying theirs.
109	        statements.move(sheet, f, sheet, t);
110	
111	        // Dropped with the person: holds, watchers, grades and contact.
112	        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", f);
113	        jdbc.update("DELETE FROM person_retirement WHERE person_id = ?", f);
114	        jdbc.update("DELETE FROM watch WHERE sheet = ? AND person_id = ?", sheet, f);
115	        jdbc.update("DELETE FROM person_grade WHERE person_id = ?", f);
116	        jdbc.update("DELETE FROM person WHERE sheet = ? AND id = ?", sheet, f);
117	
118	        audit.record("PERSON_MERGED sheet=" + sheet + " by=" + user + " from=" + from.name() + " into=" + into.name());
119	        rollup.record(sheet, user, before);
120	    }
