18	/** The people (in list order) as the screen shows them: sorted by the key, equal keys keeping list order; by name as
19	 *  names are compared, by grade A to C, by due-total smallest first with n/a last. */
20	export function useSorted(sheet: string, people: Person[]): Person[] {
21	  const [sortBy] = useSortBy();
22	  const dueOf = usePersonDueCentsOf(sheet);
23	  if (sortBy === 'name') return [...people].sort((a, b) => byNameKey(a.name, b.name));
24	  if (sortBy === 'grade') return [...people].sort((a, b) => (a.grade < b.grade ? -1 : a.grade > b.grade ? 1 : 0));
25	  if (sortBy === 'due-total') {
26	    const due = new Map(people.map((p) => [p.id, dueOf(p)]));
