/** A change of a claim's status, named by the last path segment, with the audit event it writes. */
public enum ClaimStatusChange {
public enum ClaimStatusChange {
    OPEN("CLAIM_OPENED"), SETTLE("CLAIM_SETTLED"), VOID("CLAIM_VOIDED"), APPROVE("CLAIM_APPROVED"),
    OPEN("CLAIM_OPENED"), SETTLE("CLAIM_SETTLED"), VOID("CLAIM_VOIDED"), APPROVE("CLAIM_APPROVED"),
    REJECT("CLAIM_REJECTED"), DELETE("CLAIM_DELETED"), RESTORE("CLAIM_RESTORED"),
    REJECT("CLAIM_REJECTED"), DELETE("CLAIM_DELETED"), RESTORE("CLAIM_RESTORED"),
    /** Not named in a path: a clerk's settle of a due above the clerk limit becomes this. */
    /** Not named in a path: a clerk's settle of a due above the clerk limit becomes this. */
    PEND("CLAIM_PENDING");

    private final String event;

    ClaimStatusChange(String event) {
        this.event = event;
    }

    public String event() {
        return event;
    }

    /** The change named in the path (open, settle, void, approve, reject, delete or restore), or null when there is no such change. */
    public static ClaimStatusChange of(String name) {
        for (ClaimStatusChange change : values()) {
            if (change != PEND && change.name().equalsIgnoreCase(name)) {
                return change;
            }
        }
        return null;
    }
}
=== ClaimRedater
/**
 * A steward moves an OPEN or PENDING claim to another date, on or before its person's retirement, unless it is due
 * inside a closed period. Its due-by stays as it was fixed and a figure its statement bound stays bound; so does its
 * period (the one its due-by falls in), and with it any number it has within its period. Shared by a claim's own
 * Re-date button and the bulk re-date.
 */
public class ClaimRedater {

    private final Claims claims;
    private final People people;
    private final Periods periods;
    private final Roles roles;
    private final Audit audit;
    private final Rollup rollup;

    public ClaimRedater(Claims claims, People people, Periods periods, Roles roles, Audit audit, Rollup rollup) {
        this.claims = claims;
        this.people = people;
        this.periods = periods;
        this.roles = roles;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** Re-dates the claim, writing nothing when it is refused. */
    public void redate(String sheet, String user, Claim claim, LocalDate date)
            throws InvalidClaimStatusChangeException {
        if (!Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Only a steward may re-date a claim");
        }
        if (claim.status() != ClaimStatus.OPEN && claim.status() != ClaimStatus.PENDING) {
            throw new InvalidClaimStatusChangeException("A " + claim.status() + " claim cannot be re-dated");
        }
        LocalDate old = LocalDate.parse(claim.date());
        if (periods.closedOn(sheet, LocalDate.parse(claim.dueBy()))) {
            throw new InvalidClaimStatusChangeException("A claim due inside a closed period cannot be re-dated");
        }
        Person person = people.find(sheet, claim.person());
        if (person.retiredBefore(date)) {
            throw new InvalidClaimStatusChangeException("A claim cannot be dated after its person's retirement");
        }
        Rollup.Snapshot before = rollup.take(sheet);
        // Conditional on the status and date read, so a concurrent change by another user is refused, not overwritten.
        if (!claims.redate(sheet, claim.id(), claim.status(), old, date)) {
            throw new InvalidClaimStatusChangeException("The claim changed since it was read");
        }
        Claim redated = claim.withDate(date.toString());
        audit.record("CLAIM_REDATED sheet=" + sheet + " by=" + user + " " + redated.statusAuditFields(person.name())
                + " old=" + old + " new=" + date);
        rollup.record(sheet, user, before);
    }
}
=== ClaimReassigner
/**
 * Moves a DRAFT, OPEN or PENDING claim dated outside a closed period (which may not be edited) to another person on
 * the sheet, on or before that person's retirement; only a role the permission matrix lets (by default a steward) may.
 * The claim keeps its date but takes the next number in the sequence it would be opened in (its old number is never
 * used again; a draft has none to take), loses any figure a statement bound it to, and lists as its new person's newest
 * claim. Shared by a claim's own Reassign button and the bulk reassign.
 */
public class ClaimReassigner {

    private final Claims claims;
    private final People people;
    private final Roles roles;
    private final Settings settings;
    private final Periods periods;
    private final Audit audit;
    private final Rollup rollup;
    private final ClaimStatusChanger statusChanger;

    public ClaimReassigner(Claims claims, People people, Roles roles, Settings settings, Periods periods, Audit audit,
            Rollup rollup, ClaimStatusChanger statusChanger) {
        this.claims = claims;
        this.people = people;
        this.roles = roles;
        this.settings = settings;
        this.periods = periods;
        this.audit = audit;
        this.rollup = rollup;
        this.statusChanger = statusChanger;
    }

    /**
     * Moves the claim to the person, writing nothing when it is refused. {@code samePerson} lets a claim already with
     * the person be moved to them again (the bulk reassign takes every selected claim to the one person).
     */
    public void reassign(String sheet, String user, Claim claim, Long toId, boolean samePerson)
            throws InvalidClaimStatusChangeException {
        if (!settings.permits(sheet, "reassign", roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Your role may not reassign a claim");
        }
        if (claim.status() != ClaimStatus.DRAFT && claim.status() != ClaimStatus.OPEN
                && claim.status() != ClaimStatus.PENDING) {
            throw new InvalidClaimStatusChangeException("A " + claim.status() + " claim cannot be reassigned");
        }
        if (periods.closedOn(sheet, LocalDate.parse(claim.dueBy()))) {
            throw new InvalidClaimStatusChangeException("A claim due inside a closed period cannot be reassigned");
        }
        Person from = people.find(sheet, claim.person());
        Person to = toId == null ? null : people.find(sheet, toId);
        if (to == null || (!samePerson && to.id() == claim.person())) {
            throw new InvalidClaimStatusChangeException("A claim is reassigned to another person on the sheet");
        }
        if (to.retiredBefore(LocalDate.parse(claim.date()))) {
            throw new InvalidClaimStatusChangeException("A claim cannot move to a person retired before its date");
        }
        Rollup.Snapshot before = rollup.take(sheet);
        // Conditional on the person and status read, so a concurrent change by another user is refused, not overwritten.
        if (!claims.reassign(sheet, claim.id(), claim.person(), claim.status(), to.id())) {
            throw new InvalidClaimStatusChangeException("The claim changed since it was read");
        }
        // A numbered claim is renumbered as if opened now; the number it showed before is dropped.
        Claim moved = claim;
        if (claim.status() != ClaimStatus.DRAFT) {
            if (claim.periodNumber() != null) {
                claims.setPeriodNumber(sheet, claim.id(), null);
            }
            moved = statusChanger.number(sheet, claim.withPeriodNumber(null));
        }
        audit.record("CLAIM_REASSIGNED sheet=" + sheet + " by=" + user + " " + moved.statusAuditFields(to.name())
                + " from=" + from.name() + " to=" + to.name());
        rollup.record(sheet, user, before);
    }
}
=== BulkSettleClaims
/**
 * Settles each selected claim in list order (people by their list positions, newest claim first within a
 * person) by the rules of settling one claim, as the signed-in user; one a clerk's settle sends to PENDING counts as
 * settled. It is all or nothing: when any selected claim cannot be settled none is, every one counts refused and
 * nothing is written. Otherwise the bulk settle is the sheet's next batch, each claim it settled carries the batch's
 * number, and after the claims' own lines a BATCH_SETTLED line gives its count and the frozen figures of those
 * SETTLED added up.
 */
public class BulkSettleClaims {
    public void settle(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @RequestBody BulkSettleRequest request, Claims claims, People people, ClaimStatusChanger changer,
            SettleBatches batches, Audit audit,
            ObjectResponse<BulkSettleResponse> response) {
        Map<Long, Integer> personOrder = new HashMap<>();
        for (Person person : people.list(sheet)) {
            personOrder.put(person.id(), personOrder.size());
        }
        List<Claim> selected = new ArrayList<>();
        int refused = 0;
        for (Long id : new LinkedHashSet<>(request == null || request.claims() == null ? List.of() : request.claims())) {
            Claim claim = id == null ? null : claims.find(sheet, id);
            if (claim == null) {
                refused++;
            } else {
                selected.add(claim);
            }
        }
        // Newest first within a person, as the sheet lists them.
        Map<Long, Integer> listOrder = new HashMap<>();
        for (Claim claim : claims.list(sheet)) {
            listOrder.put(claim.id(), listOrder.size());
        }
        selected.sort(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.person(), Integer.MAX_VALUE))
                .thenComparing((Claim c) -> listOrder.getOrDefault(c.id(), Integer.MAX_VALUE)));
        // All or nothing: when any selected claim cannot be settled by the user, none is and every one counts refused.
        boolean refusal = refused > 0;
        for (Claim claim : selected) {
            try {
                changer.vet(sheet, user, claim, ClaimStatusChange.SETTLE, null);
            } catch (InvalidClaimStatusChangeException e) {
                refusal = true;
            }
        }
        if (refusal) {
            response.send(new BulkSettleResponse(0, refused + selected.size(), claims.list(sheet), batches.last(sheet)));
            return;
        }
        int settled = 0;
        Integer batch = null;
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim claim : selected) {
            try {
                // Re-read so each claim is settled as the store holds it after the ones before it.
                changer.change(sheet, user, claims.find(sheet, claim.id()), ClaimStatusChange.SETTLE);
                if (batch == null) {
                    batch = batches.next(sheet, user);
                }
                claims.setBatch(sheet, claim.id(), batch);
                settled++;
                Claim after = claims.find(sheet, claim.id());
                if (after.status() == ClaimStatus.SETTLED && after.settledDue() != null) {
                    total = total.add(new BigDecimal(after.settledDue()));
                }
            } catch (InvalidClaimStatusChangeException lost) {
                refused++;
            }
        }
        if (batch != null) {
            audit.record("BATCH_SETTLED sheet=" + sheet + " by=" + user + " batch=" + batch + " count=" + settled
                    + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
        }
        response.send(new BulkSettleResponse(settled, refused, claims.list(sheet), batches.last(sheet)));
    }
}
