            for (String all : kept) {
                for (String tag : all.split(",")) {
                    if (!tag.isEmpty()) {
                        jdbc.update("MERGE INTO sheet_tag (sheet, tag) KEY (sheet, tag) VALUES (?, ?)", sheet, tag);
