221	    const product = (figure + total) * pct;
222	    const quotient = product / 10000n;
223	    const remainder = product % 10000n;
224	    const up = remainder > 5000n || (remainder === 5000n && (roundsHalfUp(claim, late) || quotient % 2n === 1n));
