232	export function claimDueCents(claim: Claim, pct: string | undefined, floor: DatedCents, late: Late): bigint | undefined {
233	  const figure = claimFigureCents(claim, pct, floor, roundsHalfUp(claim, late));
234	  if (figure === undefined || claim.settledDue !== null || correction(claim)) return figure;
