268	  // A claim has a figure apart from today's grade when it keeps one, or when another grade in force on its date gives one.
269	  const apart = (c: Claim) => {
270	    const then = gradeOn(person, c.date);
271	    return fixed(c) || (then !== undefined && then !== person.grade && claimFigureCents(c, rateOf(rates, then, c.date), floor) !== undefined)
