278	/** A person's settled-total and open-total (in hundredths): the dues of their SETTLED claims that count (at their
279	 *  frozen figures, corrections included) and of their OPEN and PENDING ones that count (see {@link counted}). Together
280	 *  they make the due-total before the cap; a claim with no due adds nothing. */
281	export function splitDueCents(
282	  claims: Claim[],
283	  rates: Rate[],
284	  person: Person,
285	  floor: DatedCents,
286	  late: Late,
287	): { settled: bigint; open: bigint } {
288	  const split = { settled: 0n, open: 0n };
289	  for (const c of counted(claims.filter((c) => c.person === person.id), [person])) {
290	    const due = claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n;
291	    if (c.status === 'SETTLED') split.settled += due;
292	    else if (isOpen(c)) split.open += due;
293	  }
294	  return split;
295	}
