297	/** A person's recent settled figure: the sum of their SETTLED claims' frozen figures dated within the 90 days up to
298	 *  and including the sheet's today (today and the 89 days before it); a claim settled with no figure adds nothing. */
299	export function recentSettledCents(claims: Claim[], person: Person, today: string | undefined): bigint {
300	  if (today === undefined) return 0n;
301	  const since = plusDays(today, -89);
302	  return claims
303	    .filter((c) => c.person === person.id && c.status === 'SETTLED' && c.date >= since && c.date <= today)
304	    .reduce((sum, c) => sum + (c.settledDue === null ? 0n : hundredths(c.settledDue)), 0n);
305	}
