307	/** Whether a person is active: they have an OPEN or PENDING claim that counts (see {@link counted}) dated within the
308	 *  30 days up to and including the sheet's today (today and the 29 days before it). */
309	export function isActive(claims: Claim[], person: Person, today: string | undefined): boolean {
310	  if (today === undefined) return false;
311	  const since = plusDays(today, -29);
312	  return counted(claims.filter((c) => c.person === person.id), [person]).some(
313	    (c) => isOpen(c) && c.date >= since && c.date <= today,
314	  );
315	}
