317	/** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by plus its grace before the sheet's today. */
318	export function overdue(claim: Claim, late: Late): boolean {
319	  return isOpen(claim) && !claim.deferred && late.today !== undefined && late.graceBy(claim) < late.today;
320	}
321	
322	/** The overdue claims that count (see {@link counted}) among a person's or the sheet's claims, and the sum of
323	 *  their dues (in hundredths; a claim with no due adds nothing). */
324	export function overdueCents(
325	  claims: Claim[],
326	  people: Person[],
327	  rates: Rate[],
328	  late: Late,
329	  floor: DatedCents,
330	): { count: number; cents: bigint } {
331	  const byId = new Map(people.map((p) => [p.id, p]));
332	  const overdueClaims = counted(claims, people).filter((c) => byId.has(c.person) && overdue(c, late));
333	  const cents = overdueClaims.reduce(
334	    (sum, c) => sum + (claimDueCents(c, rateOf(rates, gradeOn(byId.get(c.person)!, c.date), c.date), floor, late) ?? 0n),
335	    0n,
336	  );
337	  return { count: overdueClaims.length, cents };
