183	    68	            Periods periods) throws InvalidClaimException {
184	    69	        String[] fields = line.split(",", 4);
185	    70	        String name = fields[0].trim();
186	    71	        String amount = fields.length > 1 ? fields[1].trim() : "";
187	    72	        String date = fields.length > 2 ? fields[2].trim() : "";
