91	/** Each period's live due-total per person (in hundredths, by period name then person id): the part of the period's
92	 *  due-total from the person's claims (see {@link periodDueCents}), so the people's add up to the period's. */
93	export function personPeriodDueCents(
94	  periods: Period[],
95	  claims: Claim[],
96	  people: Person[],
97	  rates: Rate[],
98	  floor: DatedCents,
99	  late: Late,
100	): Map<string, Map<number, bigint>> {
101	  const byId = new Map(people.map((p) => [p.id, p]));
102	  const totals = new Map<string, Map<number, bigint>>();
103	  for (const c of claims) {
104	    const period = periodOf(periods, c.dueBy);
105	    const person = byId.get(c.person);
106	    if (period === undefined || person === undefined || !countedOn(c, person, period.to)) continue;
107	    const due = claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n;
108	    const byPerson = totals.get(period.name) ?? new Map<number, bigint>();
109	    byPerson.set(person.id, (byPerson.get(person.id) ?? 0n) + due);
110	    totals.set(period.name, byPerson);
111	  }
112	  return totals;
113	}
