    23	 * Responds with a preview of a candidate rate applied to a grade on every date: the OPEN and PENDING claims of
    24	 * people on that grade (the one in force on the claim's date) whose due would differ, and the sum of the
    25	 * differences. A claim bound by a statement keeps its figure; a settled one is not counted. Nothing is written.
    26	 */
    27	public class RespondWithRatePreview {
    28	    private static final Set<String> GRADES = Set.of("A", "B", "C");
    29	    private static final Pattern PCT = Pattern.compile("\\d{1,7}(\\.\\d{1,2})?");
    30	
    31	    public void respond(@PathVariable("sheet") String sheet,
    32	            @RequestParam(value = "grade", required = false) String grade,
    33	            @RequestParam(value = "pct", required = false) String pct, Rates rates, People people, Claims claims,
    34	            Settings settings, SheetClock clock, ObjectResponse<RatePreview> response) throws InvalidRateException {
    35	        String g = grade == null ? "" : grade.trim();
    36	        String p = pct == null ? "" : pct.trim();
    37	        if (!GRADES.contains(g)) {
    38	            throw new InvalidRateException("Grade must be A, B or C");
    39	        }
    40	        if (!PCT.matcher(p).matches()) {
    41	            throw new InvalidRateException("The rate must be a percent of 0.00 or more with up to two decimals");
    42	        }
    43	        List<Rate> current = rates.list(sheet);
    44	        List<Rate> candidate = new ArrayList<>(current.stream().filter((r) -> !r.grade().equals(g)).toList());
    45	        candidate.add(new Rate(g, new BigDecimal(p).setScale(2).toPlainString(), null, null));
    46	        LocalDate today = clock.today(sheet);
    47	        Dated floor = settings.floor(sheet);
    48	        Late late = settings.late(sheet, today);
    49	        List<Claim> all = claims.list(sheet);
    50	        int count = 0;
    51	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
    52	        for (Person person : people.list(sheet)) {
    53	            for (Claim claim : all) {
    54	                if (claim.person() != person.id()
    55	                        || (claim.status() != ClaimStatus.OPEN && claim.status() != ClaimStatus.PENDING)
    56	                        || claim.bound() || !g.equals(person.gradeOn(claim.date()))) {
    57	                    continue;
    58	                }
    59	                BigDecimal was = claim.due(current, g, floor, late);
    60	                BigDecimal now = claim.due(candidate, g, floor, late);
    61	                if (was == null ? now != null : now == null || was.compareTo(now) != 0) {
    62	                    count++;
    63	                    diff = diff.add(now == null ? BigDecimal.ZERO : now)
    64	                            .subtract(was == null ? BigDecimal.ZERO : was);
    65	                }
    66	            }
    67	        }
    68	        response.send(new RatePreview(count, diff.setScale(2).toPlainString()));
    69	    }
    70	}
