25	// A person's statements: how many, the last one's due-total and date, the button that takes the next and the one
26	// that cancels the last. Taking one binds their counting claims to their figures now, and cancelling one makes the
27	// claims it bound live again, so the claims are re-read before the count moves on. A date beside the button takes
28	// the statement as of that date (blank: now); it is cleared once the statement is taken or refused, so a refused date
29	// never carries into the next press, and changing it clears the statement's error.
30	function PersonStatements({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
31	  const queryClient = useQueryClient();
32	  const { data: all = [] } = useStatements(sheet);
33	  const mine = all.find((s) => s.person === person.id);
34	  const [asof, setAsof] = useState('');
35	  const take = useMutation({
36	    mutationKey: personActionKey(sheet, person.id),
37	    mutationFn: (date: string) =>
38	      postJson<StatementSummary[]>(byUser(`${peoplePath(sheet)}/${person.id}/statement`, user), { asof: date }),
39	    onSuccess: async (updated) => {
40	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
41	      queryClient.setQueryData(statementsKey(sheet), updated);
42	    },
43	    onSettled: () => setAsof(''),
44	  });
45	  const cancel = useMutation({
46	    mutationKey: personActionKey(sheet, person.id),
47	    mutationFn: () =>
48	      postJson<StatementSummary[]>(byUser(`${peoplePath(sheet)}/${person.id}/unstate`, user), {}),
49	    onSuccess: async (updated) => {
50	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
51	      queryClient.setQueryData(statementsKey(sheet), updated);
52	    },
53	  });
54	  const act = useSubmitOnce(take);
55	  const actCancel = useSubmitOnce(cancel);
56	  const latest = useIsLatest(personActionKey(sheet, person.id), take.submittedAt);
57	  const latestCancel = useIsLatest(personActionKey(sheet, person.id), cancel.submittedAt);
58	
59	  return (
60	    <>
61	      <td data-testid="person-statement-count">{mine?.count ?? 0}</td>
62	      <td data-testid="person-stated-total">{mine?.lastDueTotal ?? ''}</td>
63	      <td data-testid="person-statement-date">{mine?.lastDate ?? ''}</td>
64	      <td>
65	        <input
66	          type="date"
67	          data-testid="person-statement-asof"
68	          aria-label="Statement as of"
69	          value={asof}
70	          onChange={(e) => {
71	            setAsof(e.target.value);
72	            take.reset();
73	          }}
74	        />{' '}
75	        <button type="button" data-testid="person-statement" disabled={take.isPending} onClick={() => act(asof)}>
76	          Statement
77	        </button>{' '}
78	        <button type="button" data-testid="person-unstate" disabled={cancel.isPending} onClick={() => actCancel()}>
79	          Cancel statement
80	        </button>
81	        {take.isError && latest && (
82	          <span data-testid="person-error" role="alert">
83	            {' '}The statement could not be taken.
84	          </span>
85	        )}
86	        {cancel.isError && latestCancel && !(take.isError && latest) && (
87	          <span data-testid="person-error" role="alert">
88	            {' '}The statement could not be cancelled.
89	          </span>
90	        )}
91	      </td>
92	    </>
93	  );
94	}
