6	// A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote or a line break.
7	const csvValue = (v: string) => (/[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);
8	
9	// The button that downloads the pools as CSV: one line per member, pools in the order added and members in the
10	// order added, a pool member as pool:<name>, and the cut as its row shows it (empty when none). The pools are
11	// re-read first, so a change elsewhere (a retirement, a setting) is reflected, and the list shows the same.
12	function ExportPools({ sheet }: { sheet: string; user: string }) {
13	  const queryClient = useQueryClient();
14	
15	  const download = async () => {
16	    const pools = await queryClient.fetchQuery({
17	      queryKey: poolsKey(sheet),
18	      queryFn: () => getJson<Pool[]>(poolsPath(sheet)),
19	      staleTime: 0,
20	    });
21	    const lines = [
22	      'pool,member,share,cut',
23	      ...pools.flatMap((pool) =>
24	        pool.members.map((m) =>
25	          [pool.name, m.memberPool !== null ? `pool:${m.memberPool}` : m.name, m.share, m.cut].map(csvValue).join(','),
26	        ),
27	      ),
28	    ];
29	    const url = URL.createObjectURL(new Blob([lines.map((l) => `${l}\n`).join('')], { type: 'text/csv' }));
30	    const a = document.createElement('a');
31	    a.href = url;
32	    a.download = `pools-${sheet}.csv`;
33	    document.body.appendChild(a);
34	    a.click();
35	    a.remove();
36	    setTimeout(() => URL.revokeObjectURL(url), 1000);
37	  };
