15	/** A figure in ten-thousandths of a hundredth (hundredths times a share in hundredths of a percent) as hundredths,
16	 *  rounded half to even. */
17	function roundHundredths(product: bigint): bigint {
18	  const abs = product < 0n ? -product : product;
19	  let quotient = abs / 10000n;
20	  const remainder = abs % 10000n;
21	  if (remainder > 5000n || (remainder === 5000n && quotient % 2n === 1n)) quotient += 1n;
22	  return product < 0n ? -quotient : quotient;
23	}
