35	// A person's patrons, each with their share (see shareCents; shown "<name> <share>", sorted by name, comma separated),
36	// and their backing: over the patrons, each patron's settled figures of their SETTLED claims dated within the 90 days up
37	// to and including the sheet's today, times their share divided by 100, added up and rounded half to even (0.00 with
38	// none). A patron is picked from the others on the sheet and named one at a time; the server refuses a patron already
39	// named.
40	function PersonPatrons({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
41	  const queryClient = useQueryClient();
42	  const { data: everyone = [] } = usePeople(sheet);
43	  const { data: patrons = [] } = usePatrons(sheet);
44	  const { data: claims = [] } = useClaims(sheet);
45	  const today = useSheetToday(sheet);
46	  const [picked, setPicked] = useState('');
47	
48	  const mine = patrons
49	    .filter((p) => p.person === person.id)
50	    .sort((a, b) => a.named - b.named)
51	    .map((p) => everyone.find((e) => e.id === p.patron))
52	    .filter((p): p is Person => p !== undefined);
53	  const shares = shareCents(mine.length);
54	  const named = mine.map((p, i) => ({ patron: p, share: shares[i] }));
55	  const names = [...named]
56	    .sort((a, b) => a.patron.name.localeCompare(b.patron.name))
57	    .map((n) => `${n.patron.name} ${twoDecimals(n.share)}`);
58	  const backing = roundHundredths(
59	    named.reduce((sum, n) => sum + recentSettledCents(claims, n.patron, today) * n.share, 0n),
60	  );
61	  const others = everyone.filter((p) => p.id !== person.id);
62	
63	  const add = useMutation({
64	    mutationFn: (patron: number) =>
65	      postJson<Patron[]>(byUser(`${peoplePath(sheet)}/${person.id}/patrons`, user), { patron }),
66	    onSuccess: (updated) => {
67	      queryClient.setQueryData(patronsKey(sheet), updated);
68	      setPicked('');
69	    },
70	  });
71	  const send = useSubmitOnce(add);
72	
73	  return (
74	    <>
75	      <td data-testid="person-patrons">{names.join(', ')}</td>
76	      <td data-testid="person-backing">{twoDecimals(backing)}</td>
77	      <td>
78	        <select
79	          data-testid="person-patron-select"
80	          value={picked}
81	          onChange={(e) => {
82	            setPicked(e.target.value);
83	            add.reset();
84	          }}
85	        >
86	          <option value="">Patron…</option>
87	          {others.map((p) => (
88	            <option key={p.id} value={String(p.id)}>
89	              {p.name}
90	            </option>
91	          ))}
92	        </select>{' '}
93	        <button
