95	          data-testid="person-patron-add"
96	          disabled={add.isPending}
97	          onClick={() => send(picked === '' ? -1 : Number(picked))}
98	        >
99	          Add patron
100	        </button>
101	        {add.isError && (
102	          <span data-testid="person-patron-error" role="alert">
103	            {' '}A patron must be someone else on the sheet, not already named.
