20	/** Shares (in hundredths of a percent) for `count` patrons in the order they were named: 100.00 split equally, each
21	 *  rounded half to even to two decimals, with the remainder (100.00 minus the shares added up) on the first. */
22	export function shareCents(count: number): bigint[] {
23	  if (count === 0) return [];
24	  const n = BigInt(count);
25	  let each = 10000n / n;
