16	  const { data } = useSheet(sheet);
17	  const { data: settings } = useSettings(sheet);
18	  const [draft, setDraft] = useState('');
19	  const save = useMutation({
20	    mutationFn: (today: string) =>
21	      postJson<Sheet>(byUser(`/api/sheets/${encodeURIComponent(sheet)}/today`, user), { today }),
22	    onSuccess: (updated) => {
23	      queryClient.setQueryData(sheetKey(sheet), updated);
24	      // Everything on the sheet may depend on its today: re-read it all.
25	      void queryClient.invalidateQueries({
26	        predicate: (q) => q.queryKey.includes(sheet) && q.queryKey[0] !== 'sheet',
27	      });
28	    },
29	  });
30	  const send = useSubmitOnce(save);
31	  const archive = useMutation({
32	    mutationFn: () => postJson<Sheet>(byUser(`/api/sheets/${encodeURIComponent(sheet)}/archive`, user), {}),
33	    onSuccess: (updated) => queryClient.setQueryData(sheetKey(sheet), updated),
34	  });
35	
36	  const [cloneTo, setCloneTo] = useState('');
