3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.ArrayList;
6	import java.util.Collections;
7	import java.util.LinkedHashMap;
8	import java.util.List;
9	import java.util.Map;
10	import java.util.Objects;
11	import net.officefloor.hq.app.Audit;
12	import net.officefloor.hq.app.claim.Claim;
13	import net.officefloor.hq.app.claim.Claims;
14	import net.officefloor.hq.app.claim.Late;
15	import net.officefloor.hq.app.person.People;
16	import net.officefloor.hq.app.person.Person;
17	import net.officefloor.hq.app.rate.Rate;
18	import net.officefloor.hq.app.rate.Rates;
19	import net.officefloor.hq.app.setting.Dated;
20	import net.officefloor.hq.app.setting.Settings;
21	import net.officefloor.hq.app.sheet.SheetClock;
22	import org.springframework.stereotype.Service;
23	
24	/**
25	 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total, and the sheet's
26	 * claimed-total, due-total and overdue-total (the totals leave out the single highest and lowest person's figure when
27	 * three or more people have one). A change takes them before it writes, then {@link #record} audits the ones it moved: a ROLLUP line
28	 * per person whose figures changed (in list order, by position; a new person counts as changed), then a TOTALS
29	 * line when the sheet's totals changed, then an ALERT line per person whose due-total crossed above the sheet's alert
30	 * threshold (from at or below it, or no due-total), in list order.
31	 */
32	@Service
33	public class Rollup {
34	
35	    /**
36	     * A person's figures: claimed (two decimals), due-total (two decimals, or n/a) and overdue-total (the dues of
37	     * their counted overdue claims, two decimals).
38	     */
39	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
40	    }
41	
42	    /** The sheet's figures at one moment: per person id, in list order, and the totals. */
43	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
44	    }
45	
46	    private final People people;
47	    private final Claims claims;
48	    private final Rates rates;
49	    private final SheetClock clock;
50	    private final Settings settings;
51	    private final Audit audit;
52	
53	    public Rollup(People people, Claims claims, Rates rates, SheetClock clock, Settings settings, Audit audit) {
54	        this.people = people;
55	        this.claims = claims;
56	        this.rates = rates;
57	        this.clock = clock;
58	        this.settings = settings;
59	        this.audit = audit;
60	    }
61	
62	    /** The sheet's figures now. */
63	    public Snapshot take(String sheet) {
64	        LocalDate today = clock.today(sheet);
65	        List<Rate> sheetRates = rates.list(sheet);
66	        Dated floor = settings.floor(sheet);
67	        BigDecimal cap = settings.cap(sheet);
68	        Late late = settings.late(sheet, today);
69	        List<Claim> all = claims.list(sheet);
70	        Map<Long, Figures> figures = new LinkedHashMap<>();
71	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
72	        List<BigDecimal> dueFigures = new ArrayList<>();
73	        List<BigDecimal> overdueFigures = new ArrayList<>();
74	        for (Person person : people.list(sheet)) {
75	            List<Claim> mine = all.stream().filter((c) -> c.person() == person.id() && person.counts(c)).toList();
76	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
77	            BigDecimal due = BigDecimal.ZERO.setScale(2);
78	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
79	            for (Claim claim : mine) {
80	                if (!claim.correction()) {
81	                    claimed = claimed.add(new BigDecimal(claim.amount()));
82	                }
83	                BigDecimal d = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
84	                due = d == null ? due : due.add(d);
85	                if (d != null && late.overdue(claim, person.gradeOn(claim.date()))) {
86	                    overdue = overdue.add(d);
87	                }
88	            }
89	            // n/a when the grade has no rate on the sheet's today, unless a claim has a figure apart from it.
90	            boolean na = Rate.on(sheetRates, person.grade(), today) == null
91	                    && mine.stream().noneMatch((c) -> person.figureApartFrom(c, today, sheetRates, floor));
92	            due = Settings.capped(due, cap);
93	            claimedTotal = claimedTotal.add(claimed);
94	            overdueFigures.add(overdue);
95	            if (!na) {
96	                dueFigures.add(due);
97	            }
98	            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), na ? "n/a" : due.toPlainString(),
99	                    overdue.toPlainString()));
100	        }
101	        return new Snapshot(figures, claimedTotal.toPlainString(), trimmedSum(dueFigures).toPlainString(),
102	                trimmedSum(overdueFigures).toPlainString());
103	    }
104	
105	    /** Adds up the people's figures, leaving out the single highest and the single lowest when three or more have one. */
106	    static BigDecimal trimmedSum(List<BigDecimal> figures) {
107	        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
108	        if (figures.size() < 3) {
109	            return sum;
110	        }
111	        return sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
112	    }
113	
114	    /** Audits the figures the change moved since {@code before}, after the change's own lines. */
115	    public void record(String sheet, String user, Snapshot before) {
116	        Snapshot after = take(sheet);
117	        String prefix = " sheet=" + sheet + " by=" + user + " ";
118	        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
119	            Figures now = entry.getValue();
120	            Figures was = before.people().get(entry.getKey());
121	            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
122	                    || !was.overdueTotal().equals(now.overdueTotal())) {
123	                audit.record("ROLLUP" + prefix + "person=" + now.name() + " claimed=" + now.claimed() + " due-total="
124	                        + now.dueTotal() + " overdue-total=" + now.overdueTotal());
125	            }
126	        }
127	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
128	                || !Objects.equals(before.dueTotal(), after.dueTotal())
129	                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
130	            audit.record("TOTALS" + prefix + "claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal()
131	                    + " overdue-total=" + after.overdueTotal());
132	        }
133	        BigDecimal threshold = settings.alertThreshold(sheet);
134	        if (threshold == null) {
135	            return;
136	        }
137	        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
138	            Figures now = entry.getValue();
139	            Figures was = before.people().get(entry.getKey());
140	            if (above(now, threshold) && (was == null || !above(was, threshold))) {
141	                audit.record("ALERT" + prefix + "name=" + now.name() + " due-total=" + now.dueTotal());
142	            }
143	        }
144	    }
145	
146	    /** Whether the person has a due-total above the threshold. */
147	    private static boolean above(Figures figures, BigDecimal threshold) {
148	        return !"n/a".equals(figures.dueTotal()) && new BigDecimal(figures.dueTotal()).compareTo(threshold) > 0;
149	    }
150	}
