2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.time.temporal.ChronoUnit;
7	import java.util.List;
8	import java.util.Map;
9	import net.officefloor.hq.app.setting.Dated;
10	import net.officefloor.hq.app.setting.DatedValue;
11	import net.officefloor.hq.app.setting.Settings;
12	
13	/**
14	 * What makes an overdue claim's late charge: the sheet's late percent (two decimals) by date, the one in force on each 30-day boundary after the claim's due-by, and its today; a claim is due
15	 * by the due-by fixed when it was added. The charge is never bound by a statement: it follows the sheet's today.
16	 * It also carries the sheet's policy date, which decides how a claim's live figures round, and each grade's grace
17	 * as recorded by from-date: the days a claim of a person whose grade in force on its date has a grace in force on
18	 * that date is given past its due-by before it is overdue.
19	 */
20	public record Late(Dated pct, LocalDate today, LocalDate policy, Map<String, List<DatedValue>> grace) {
21	
22	    /**
23	     * How the claim's live figures round: half up when it rounds on a date (its own, or for a correction the date of
24	     * the claim it corrects) before the policy date, half to even on or after it.
25	     */
26	    public RoundingMode rounding(Claim claim) {
27	        return LocalDate.parse(claim.roundsOn()).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
28	    }
29	
30	    /**
31	     * The date the claim's overdue days are counted from: its due-by (fixed when it was added) plus the grace of the
32	     * grade (its person's in force on its date; null for none) in force on its date, if any.
33	     */
34	    public LocalDate graceBy(Claim claim, String grade) {
35	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
36	        List<DatedValue> history = grade == null ? null : grace.get(grade);
37	        String days = history == null ? "" : Settings.on(history, LocalDate.parse(claim.date()));
38	        return days.isEmpty() ? dueBy : dueBy.plusDays(Integer.parseInt(days));
39	    }
40	
41	    /** Whether the claim is overdue: OPEN or PENDING, not deferred, with its {@link #graceBy} before the sheet's today. */
42	    public boolean overdue(Claim claim, String grade) {
43	        return !claim.deferred() && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING) && graceBy(claim, grade).isBefore(today);
44	    }
45	
46	    /**
47	     * The claim's late charge on its figure, compounding: for each full 30 days it is overdue, the late percent in force
48	     * on that boundary (its {@link #graceBy} plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries
49	     * before it, rounded in hundredths by the claim's {@link #rounding}, the charges added up (a boundary at 0.00 adds
50	     * nothing); 0.00 when it is not overdue, and always for a correction.
51	     */
52	    public BigDecimal charge(Claim claim, String grade, BigDecimal figure) {
53	        BigDecimal total = BigDecimal.ZERO.setScale(2);
54	        if (figure == null || claim.correction() || !overdue(claim, grade)) {
55	            return total;
56	        }
57	        LocalDate dueBy = graceBy(claim, grade);
58	        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
59	        for (long k = 1; k <= periods; k++) {
60	            BigDecimal boundaryPct = pct.on(dueBy.plusDays(30 * k));
61	            if (boundaryPct.signum() != 0) {
62	                total = total.add(figure.add(total).multiply(boundaryPct).movePointLeft(2).setScale(2, rounding(claim)));
63	            }
64	        }
65	        return total;
66	    }
67	}
