3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.util.Comparator;
7	import java.util.List;
8	
9	/**
10	 * A grade's rate on a sheet: a percent with two decimals, as the screen shows it, in force from its from-date
11	 * (yyyy-MM-dd; null when it applies from the beginning of time) through its to-date (null when it has no end). Its
12	 * level is the sheet it is kept on: 0 this sheet's own, 1 its parent's, 2 its parent's parent, up to {@link #LEVELS}.
13	 */
14	public record Rate(String grade, String pct, String from, String to, int level) {
15	
16	    /** The most levels up a sheet's parents give it rates. */
17	    public static final int LEVELS = 3;
18	
19	    /** A sheet's own rate. */
20	    public Rate(String grade, String pct, String from, String to) {
21	        this(grade, pct, from, to, 0);
22	    }
23	
24	    /** This rate as one inherited from the levels up. */
25	    public Rate up(int levels) {
26	        return new Rate(grade, pct, from, to, level + levels);
27	    }
28	
29	    /**
30	     * The percent the grade's rates give on a date: the one whose from-date is the latest on or before it, or null
31	     * when the date is before every rate the grade has, or after the to-date of that one. When a level gives none, the
32	     * next level up is used.
33	     */
34	    public static String on(List<Rate> rates, String grade, LocalDate date) {
35	        for (int level = 0; level <= LEVELS; level++) {
36	            String pct = on(rates, grade, date, level);
37	            if (pct != null) {
38	                return pct;
39	            }
40	        }
41	        return null;
42	    }
43	
44	    private static String on(List<Rate> rates, String grade, LocalDate date, int level) {
45	        return rates.stream().filter((r) -> r.grade().equals(grade) && r.level() == level)
46	                .filter((r) -> r.from() == null || !LocalDate.parse(r.from()).isAfter(date))
47	                .max(Comparator.comparing((Rate r) -> r.from() == null ? LocalDate.MIN : LocalDate.parse(r.from())))
48	                .filter((r) -> r.to() == null || !LocalDate.parse(r.to()).isBefore(date))
49	                .map(Rate::pct).orElse(null);
50	    }
51	
52	    /** An amount times a percent, divided by 100, in hundredths rounded half to even; null when there is no rate. */
53	    public static BigDecimal due(String amount, String pct) {
54	        return due(amount, pct, RoundingMode.HALF_EVEN);
55	    }
56	
57	    /**
58	     * An amount times a percent, divided by 100, in hundredths rounded by the mode (on the magnitude, so a negative
59	     * amount rounds as its positive would); null when there is no rate.
60	     */
61	    public static BigDecimal due(String amount, String pct, RoundingMode rounding) {
62	        return pct == null ? null
63	                : new BigDecimal(amount).multiply(new BigDecimal(pct)).movePointLeft(2).setScale(2, rounding);
64	    }
65	}
